INSERT INTO "hadith_evidence" VALUES(1,1,'اللَّهم أنت الأول فليس قبلك شيء، أنت الآخرُ فليس بعدك شيء، وأنت الظاهرُ فليس فوقك شيء،
INSERT INTO "hadith_evidence" VALUES(2,2,'اللَّهم أنت الأول فليس قبلك شيء، أنت الآخرُ فليس بعدك شيء، وأنت الظاهرُ فليس فوقك شيء،
INSERT INTO "hadith_evidence" VALUES(3,3,'اللَّهم أنت الأول فليس قبلك شيء، أنت الآخرُ فليس بعدك شيء، وأنت الظاهرُ فليس فوقك شيء،
INSERT INTO "hadith_evidence" VALUES(4,4,'اللَّهم أنت الأول فليس قبلك شيء، أنت الآخرُ فليس بعدك شيء، وأنت الظاهرُ فليس فوقك شيء،
INSERT INTO "hadith_evidence" VALUES(5,8,'إنَّ اللَّه يقول: الكبرياء ردائي، والعظمة إزاري، فمن نازعني واحداً منهما عذبته','أخرجه مسلم في كتاب البر والصلة والآداب، باب تحريم الكبر، برقم ٢٦٢٠.');
INSERT INTO "hadith_evidence" VALUES(6,11,'سمع اللَّه لمن حمده',NULL);
INSERT INTO "hadith_evidence" VALUES(7,25,'إن اللَّه يقول: «يا ابن آدم إنك لو أتيتني بقراب الأرض خطايا ثم لقيتني لا تشرك بي شيئاً لأتيتك بقرابها مغفرة','أخرجه الترمذي في كتاب الدعوات، باب خلق الله مائة رحمة، برقم ٣٥٤٠، وحسنه الألباني في صحيح الجامع ٥/ ٥٤٨ ..');
INSERT INTO "hadith_evidence" VALUES(8,26,'إن اللَّه يقول: «يا ابن آدم إنك لو أتيتني بقراب الأرض خطايا ثم لقيتني لا تشرك بي شيئاً لأتيتك بقرابها مغفرة','أخرجه الترمذي في كتاب الدعوات، باب خلق الله مائة رحمة، برقم ٣٥٤٠، وحسنه الألباني في صحيح الجامع ٥/ ٥٤٨ ..');
INSERT INTO "hadith_evidence" VALUES(9,27,'إن اللَّه يقول: «يا ابن آدم إنك لو أتيتني بقراب الأرض خطايا ثم لقيتني لا تشرك بي شيئاً لأتيتك بقرابها مغفرة','أخرجه الترمذي في كتاب الدعوات، باب خلق الله مائة رحمة، برقم ٣٥٤٠، وحسنه الألباني في صحيح الجامع ٥/ ٥٤٨ ..');
INSERT INTO "hadith_evidence" VALUES(10,31,'احفظ اللَّه يحفظك','أخرجه الترمذي في كتاب صفة القيامة، باب ٥٩، برقم ٢٥١٦، ولحاكم، ٣/ ٥٤١، وقال: ((هذا حديث كبير عال)). وصححه الألباني في صحيح الجامع، برقم ٧٩٥٧.');
INSERT INTO "hadith_evidence" VALUES(11,38,'السَّيِّدُ اللَّه تبارك وتعالى','أخرجه أبو داود في كتاب الأدب، باب في كراهية التمادح، برقم ٤٨٠٦، وابن السني في عمل اليوم ولليلة، برقم ٣٨٧، والنسائي في عمل اليوم والليلة، برقم ٢٤٥، وأحمد، ٤/ ٢٤، ٢٥، وصححه الألباني في صحيح الجامع، برقم ٣٧٠٠، وإسناده صحيح، وانظر: فتح المجيد، ص٦١٣، بتحقيق الأرنؤوط.');
INSERT INTO "hadith_evidence" VALUES(12,39,'السَّيِّدُ اللَّه تبارك وتعالى','أخرجه أبو داود في كتاب الأدب، باب في كراهية التمادح، برقم ٤٨٠٦، وابن السني في عمل اليوم ولليلة، برقم ٣٨٧، والنسائي في عمل اليوم والليلة، برقم ٢٤٥، وأحمد، ٤/ ٢٤، ٢٥، وصححه الألباني في صحيح الجامع، برقم ٣٧٠٠، وإسناده صحيح، وانظر: فتح المجيد، ص٦١٣، بتحقيق الأرنؤوط.');
INSERT INTO "hadith_evidence" VALUES(13,45,'إن اللَّه هو الحكمُ وإليه الحكم','أخرجه أبو داود في كتاب الأدب، باب في تغيير الاسم القبيح، برقم ٤٩٥٥، والنسائي في كتاب آداب القضاة، باب إذا حكَّموا رجلاً فقضى بينهم، برقم ٥٣٨٤، والحاكم، ١/ ٢٣، والطبراني في الكبير، ٢٢/ ١٧٩، ١٨٠، ورقم ٤٦٦، ٤٧٠، وابن حبان كما في الموارد، ٦/ ٢١٤، برقم ١٩٣٧، وإسناده جيد. انظر: فتح المجيد بشرح كتاب التوحي');
INSERT INTO "hadith_evidence" VALUES(14,56,'إنَّ اللَّه هوَ المسَعِّرُ القابضُ الباسطُ الرَّازِقُ','أخرجه أبو داود في كتاب البيوع والإجارات، باب في التسعير، برقم ٣٤٥١، والترمذي في كتاب البيوع، باب في التسعير، برقم ١٣١٤، وابن ماجه في كتاب التجارات، باب من كره أن يسعر، برقم ٢٢٠٠، وأحمد في المسند، ٣/ ١٥٦، وصححه الترمذي، وكذا الألباني في صحيح الجامع، برقم ١٨٤٦.');
INSERT INTO "hadith_evidence" VALUES(15,57,'إنَّ اللَّه هوَ المسَعِّرُ القابضُ الباسطُ الرَّازِقُ','أخرجه أبو داود في كتاب البيوع والإجارات، باب في التسعير، برقم ٣٤٥١، والترمذي في كتاب البيوع، باب في التسعير، برقم ١٣١٤، وابن ماجه في كتاب التجارات، باب من كره أن يسعر، برقم ٢٢٠٠، وأحمد في المسند، ٣/ ١٥٦، وصححه الترمذي، وكذا الألباني في صحيح الجامع، برقم ١٨٤٦.');
INSERT INTO "hadith_evidence" VALUES(16,60,'اللَّهم لك الحمد، أنت نور السموات والأرض ومن فيهن ...','أخرجه البخاري في كتاب الدعوات، باب الدعاء إذا انتبه بالليل، برقم ٦٣١٧، ومسلم في كتاب صلاة المسافرين وقصرها، باب الدعاء في صلاة الليل وقيامه، برقم ٧٦٩.');
INSERT INTO "hadith_evidence" VALUES(17,60,'إن اللَّه - عز وجل - لا ينام، ولا ينبغي له أن
INSERT INTO "hadith_evidence" VALUES(18,84,'إن اللَّه جميلٌ يحبُ الجمال','أخرجه مسلم في كتاب الإيمان، باب تحريم الكبر وبيانه، برقم ٩١.');
INSERT INTO "hadith_evidence" VALUES(19,84,'حجابه النور لو كشفه لأحرقت سبحات وجهه ما انتهى إليه بصره من خلقه','أخرجه مسلم في كتاب الإيمان، باب في قوله - عليه السلام -: إن الله لا ينام، برقم ١٧٩.');
INSERT INTO "hadith_evidence" VALUES(20,85,'إن اللَّه رفيق يحب الرفق، ويُعطي على الرفق ما لا يُعطي على العنف، وما لا يُعطي على ما سواه','أخرجه مسلم في كتاب البر والصلة والآداب، باب فضل الرفق، برقم ٢٥٩٣، وأخرج البخاري الجزء الأول منه في كتاب استتابة المرتدين، باب إذا عرَّض الذمي وغيره بسب النبي - صلى الله عليه وسلم -، برقم ٦٩٢٧.');
INSERT INTO "hadith_evidence" VALUES(21,86,'إن اللَّه حيي يستحي من عبده إذا مدَّ يديه إليه أن يردهما صفراً','أخرجه أبو داود في كتاب الوتر، باب الدعاء، برقم ١٤٨٨، والترمذي في كتاب الدعوات، باب ١٠٤، برقم ٣٥٥٦، وابن ماجه في كتاب الدعاء، باب رفع اليدين في الدعاء، برقم ٣٨٦٥، وأحمد في المسند، ٥/ ٤٣٨، والحاكم في المستدرك، ١/ ٤٩٧، وقال: «إسناده صحيح على شرط الشيخين». ووافقه الذهبي. وقال أبو عيسى الترمذي: «هذا حديث');
INSERT INTO "hadith_evidence" VALUES(22,86,'إن اللَّه - عز وجل - حليمٌ، حييٌ ستِّيرٌ يُحبّ الحياءَ والستر، فإذا اغتسل أحدكم فليستتر','أخرجه أبو داود في كتاب الحمّام، باب النهي عن التعري، برقم ٤٠١٢، والنسائي في كتاب الغسل، باب الاستتار عند الاغتسال، برقم ٤٠٤، وأحمد، ٤/ ٢٢٤، والبيهقي في سننه الكبرى،');
INSERT INTO "hadith_evidence" VALUES(23,87,'إن اللَّه حيي يستحي من عبده إذا مدَّ يديه إليه أن يردهما صفراً','أخرجه أبو داود في كتاب الوتر، باب الدعاء، برقم ١٤٨٨، والترمذي في كتاب الدعوات، باب ١٠٤، برقم ٣٥٥٦، وابن ماجه في كتاب الدعاء، باب رفع اليدين في الدعاء، برقم ٣٨٦٥، وأحمد في المسند، ٥/ ٤٣٨، والحاكم في المستدرك، ١/ ٤٩٧، وقال: «إسناده صحيح على شرط الشيخين». ووافقه الذهبي. وقال أبو عيسى الترمذي: «هذا حديث');
INSERT INTO "hadith_evidence" VALUES(24,87,'إن اللَّه - عز وجل - حليمٌ، حييٌ ستِّيرٌ يُحبّ الحياءَ والستر، فإذا اغتسل أحدكم فليستتر','أخرجه أبو داود في كتاب الحمّام، باب النهي عن التعري، برقم ٤٠١٢، والنسائي في كتاب الغسل، باب الاستتار عند الاغتسال، برقم ٤٠٤، وأحمد، ٤/ ٢٢٤، والبيهقي في سننه الكبرى،');
INSERT INTO "hadith_evidence" VALUES(25,89,'إن اللَّه هو المُسعِّرُ، القابضُ، الباسطُ، الرَّازقُ ..','أخرجه أبو داود في كتاب البيوع والإجارات، باب في التسعير، برقم ٣٤٥١، والترمذي في كتاب البيوع، باب في التسعير، برقم ١٣١٤، وابن ماجه في كتاب التجارات، باب من كره أن يسعر، برقم ٢٢٠٠، وأحمد في المسند، ٣/ ١٥٦، وصححه الترمذي. وكذا الألباني في صحيح الجامع، برقم ١٨٤٦.');
INSERT INTO "hadith_evidence" VALUES(26,89,'من يرد اللَّه به خيراً يفقهه في الدين، واللَّه المعطي وأنا القاسم ...','أخرجه البخاري في كتاب العلم، باب من يرد الله به خيراً يفقهه في الدين، برقم ٧١، ومسلم في كتاب الزكاة، باب النهي عن المسألة، برقم ١٠٣٧/ ١٠٠.');
INSERT INTO "hadith_evidence" VALUES(27,89,'لا إله إلا اللَّه وحده لا شريك له، له الملك وله الحمدُ وهو على كل شيءٍ قدير، اللَّهم لا مانع لما أعطيت ولا مُعطي لما منعت ولا ينفع ذا الجدِّ منك الجدُّ','أخرجه البخاري في كتاب الأذان، باب الذكر بعد الصلاة، برقم ٨٤٤، ومسلم في كتاب المساجد ومواضع الصلاة، باب استحباب الذكر بعد الصلاة وبيان صفته، برقم ٥٩٣.');
INSERT INTO "hadith_evidence" VALUES(28,90,'إن اللَّه هو المُسعِّرُ، القابضُ، الباسطُ، الرَّازقُ ..','أخرجه أبو داود في كتاب البيوع والإجارات، باب في التسعير، برقم ٣٤٥١، والترمذي في كتاب البيوع، باب في التسعير، برقم ١٣١٤، وابن ماجه في كتاب التجارات، باب من كره أن يسعر، برقم ٢٢٠٠، وأحمد في المسند، ٣/ ١٥٦، وصححه الترمذي. وكذا الألباني في صحيح الجامع، برقم ١٨٤٦.');
INSERT INTO "hadith_evidence" VALUES(29,90,'من يرد اللَّه به خيراً يفقهه في الدين، واللَّه المعطي وأنا القاسم ...','أخرجه البخاري في كتاب العلم، باب من يرد الله به خيراً يفقهه في الدين، برقم ٧١، ومسلم في كتاب الزكاة، باب النهي عن المسألة، برقم ١٠٣٧/ ١٠٠.');
INSERT INTO "hadith_evidence" VALUES(30,90,'لا إله إلا اللَّه وحده لا شريك له، له الملك وله الحمدُ وهو على كل شيءٍ قدير، اللَّهم لا مانع لما أعطيت ولا مُعطي لما منعت ولا ينفع ذا الجدِّ منك الجدُّ','أخرجه البخاري في كتاب الأذان، باب الذكر بعد الصلاة، برقم ٨٤٤، ومسلم في كتاب المساجد ومواضع الصلاة، باب استحباب الذكر بعد الصلاة وبيان صفته، برقم ٥٩٣.');
INSERT INTO "hadith_evidence" VALUES(31,91,'إن اللَّه هو المُسعِّرُ، القابضُ، الباسطُ، الرَّازقُ ..','أخرجه أبو داود في كتاب البيوع والإجارات، باب في التسعير، برقم ٣٤٥١، والترمذي في كتاب البيوع، باب في التسعير، برقم ١٣١٤، وابن ماجه في كتاب التجارات، باب من كره أن يسعر، برقم ٢٢٠٠، وأحمد في المسند، ٣/ ١٥٦، وصححه الترمذي. وكذا الألباني في صحيح الجامع، برقم ١٨٤٦.');
INSERT INTO "hadith_evidence" VALUES(32,91,'من يرد اللَّه به خيراً يفقهه في الدين، واللَّه المعطي وأنا القاسم ...','أخرجه البخاري في كتاب العلم، باب من يرد الله به خيراً يفقهه في الدين، برقم ٧١، ومسلم في كتاب الزكاة، باب النهي عن المسألة، برقم ١٠٣٧/ ١٠٠.');
INSERT INTO "hadith_evidence" VALUES(33,91,'لا إله إلا اللَّه وحده لا شريك له، له الملك وله الحمدُ وهو على كل شيءٍ قدير، اللَّهم لا مانع لما أعطيت ولا مُعطي لما منعت ولا ينفع ذا الجدِّ منك الجدُّ','أخرجه البخاري في كتاب الأذان، باب الذكر بعد الصلاة، برقم ٨٤٤، ومسلم في كتاب المساجد ومواضع الصلاة، باب استحباب الذكر بعد الصلاة وبيان صفته، برقم ٥٩٣.');
INSERT INTO "hadith_evidence" VALUES(34,92,'اللَّهم اغفر لي ما قدّمت، وما أخَّرت، وما أسررتُ، وما أعلنتُ، وما أسرفت، وما أنت أعلمُ به مني. أنتَ المقدِّمُ، وأنت المؤخِّرُ. لا إله إلا أنت','أخرجه مسلم في كتاب صلاة المسافرين وقصرها، باب الدعاء في صلاة الليل وقيامه، برقم ٧٧١، وأخرجه بنحوه البخاري في كتاب الدعوات، باب قول النبي - صلى الله عليه وسلم -: «اللهم اغفر لي ما قدمت وما أخرت»، برقم ٦٣٩٨، وليس فيه: «بين التشهد والتسليم».');
INSERT INTO "hadith_evidence" VALUES(35,93,'اللَّهم اغفر لي ما قدّمت، وما أخَّرت، وما أسررتُ، وما أعلنتُ، وما أسرفت، وما أنت أعلمُ به مني. أنتَ المقدِّمُ، وأنت المؤخِّرُ. لا إله إلا أنت','أخرجه مسلم في كتاب صلاة المسافرين وقصرها، باب الدعاء في صلاة الليل وقيامه، برقم ٧٧١، وأخرجه بنحوه البخاري في كتاب الدعوات، باب قول النبي - صلى الله عليه وسلم -: «اللهم اغفر لي ما قدمت وما أخرت»، برقم ٦٣٩٨، وليس فيه: «بين التشهد والتسليم».');
INSERT INTO "hadith_evidence" VALUES(36,95,'اللَّهم إني أسألك بأن لك الحمد لا إله إلا أنت [وحدك لا شريك لك] المنّان، [يا] بديع السموات والأرض، يا ذا الجلال والإكرام، يا حيُّ يا قيوم إني أسألك الجنة وأعوذ بك من النار. فقال النبي - صلى الله عليه وسلم -: «لقد سأل اللَّه باسمه الأعظم الذي إذا سُئل به أعطى، وإذا دُعي به أجاب','أخرجه أبو داود في كتاب الوتر، باب الدعاء، برقم ١٤٩٣ - ١٤٩٥، والترمذي في كتاب الدعوات، باب ما جاء في جامع الدعوات عن النبي - صلى الله عليه وسلم -، برقم ٣٤٧٥، وابن ماجه في كتاب الدعاء، باب اسم الله الأعظم، برقم ٣٨٥٧، ٣٨٥٨، وقال الترمذي: «هذا حديث حسن غريب». وانظر: صحيح النسائي للألباني، ١/ ٢٧٩، وصحيح ');
INSERT INTO "hadith_evidence" VALUES(37,95,'المُسبلُ، والمنانُ، والمنفق سلعته بالحلِفِ الكاذب','أخرجه مسلم في كتاب الإيمان، باب بيان غلظ تحريم إسبال الإزار والمن بالعطية، برقم ١٠٦.');
INSERT INTO "hadith_evidence" VALUES(38,96,'إن اللَّه يقول: من عادى لي ولياً فقد آذنته بالحرب، وما تقرَّب إليّ عبدي بِشَيْءٍ أحبّ إليّ مما افترضته عليه، وما يزال عبدي يتقرّب إليَّ بالنوافل حتى أُحبَّه، فإذا أحببته كنت سمعه الذي يسمع به، وبصره الذي يبصر به، ويده التي يبطش بها، ورجله التي يمشي بها، وإن سألني لأُعطينّه، ولئن أستعاذني لأُعيذنّه، وما تردّدت عن شيء أنا فاعله تردّدي عن نفس المؤمن يكره الموت، وأنا أكره مساءته','أخرجه البخاري في كتاب الرقاق، باب التواضع، برقم ٦٥٠٢.');
INSERT INTO "hadith_evidence" VALUES(39,97,'قولوا اللَّه مولانا ولا مولى لكم','أخرجه البخاري في كتاب الجهاد والسير، باب ما يكره من التنازع والاختلاف في الحرب وعقوبة من عصى إمامه، برقم ٣٠٣٩، وفي كتاب المغازي، باب غزوة أحد، برقم ٤٠٤٣.');
INSERT INTO "hadith_evidence" VALUES(40,98,'اللَّهم أنت عضدي، وأنت نصيري، بك أجُول وبك أصول، وبك أقاتل','أخرجه أبو داود في كتاب الجهاد، باب ما يدعى عند اللقاء، برقم ٢٦٢٣، والترمذي في كتاب الدعوات، باب في الدعاء إذا غزا، برقم ٣٥٨٤، وقال: «هذا حديث حسن غريب». وانظر: صحيح الترمذي، ٣/ ١٨٣.');
INSERT INTO "hadith_evidence" VALUES(41,99,'اللَّهم ربّ الناس، أذهب البأس، اشف أنت الشافي، لا شفاء إلا شفاؤك، شفاء لا يغادر سقماً','أخرجه البخاري في كتاب الطب، باب رقية النبي - صلى الله عليه وسلم -، برقم ٥٧٤٣، ومسلم في كتاب السلام، باب استحباب رقية المريض، برقم ٢١٩١.');
INSERT INTO "hadith_evidence" VALUES(42,99,'اللَّهم ربّ الناس، مُذْهِب البأس، اشف أنت الشافي، لا شافي إلا أنت، شفاء لا يُغادِرُ سَقماً','أخرجه البخاري في كتاب الطب، باب رقية النبي - صلى الله عليه وسلم -، برقم ٥٧٤٢.');
INSERT INTO "hadith_evidence" VALUES(43,99,'ما أنزل اللَّه من داء إلا أنزل له شفاء','أخرجه البخاري في كتاب الطب، باب ما أنزل الله داء إلا أنزل له شفاء، برقم ٥٦٧٨.');
INSERT INTO "hadith_evidence" VALUES(44,99,'وما أدراك أنها رقية، خذوها واضربوا لي بسهم','أخرجه البخاري في كتاب الطب، باب الرقى بفاتحة الكتاب، برقم ٥٧٣٦، ومسلم في السلام، باب جواز أخذ الأجرة على الرقية بالقرآن والأذكار، برقم ٢٢٠١.');
INSERT INTO "hadith_evidence" VALUES(45,99,'أن النبي - صلى الله عليه وسلم - كان إذا اشتكى يقرأ على نفسه بالمعوذات وينفث، فلما اشتد وجعه كنت أقرأ عليه وأمسح عنه بيده، رجاء بركتها','أخرجه البخاري في كتاب الطب، باب الرقى بالقرآن والمعوذات، برقم ٥٧٣٥، ومسلم في كتاب السلام، باب رقية المريض بالمعوذات والنفث، برقم ٢١٩٢.');
