INSERT INTO "names" VALUES(1,'الأول','الأوَّلُ','الذي ليس قبله شيء، فكل ما سواه حادث مخلوق بعده','١ - الأوَّلُ ، ٢ - الآخِرُ، ٣ - الظَّاهِرُ، ٤ - الباطِنُ
INSERT INTO "names" VALUES(2,'الآخر','الآخِرُ','الذي ليس بعده شيء، الباقي بعد فناء خلقه','١ - الأوَّلُ ، ٢ - الآخِرُ، ٣ - الظَّاهِرُ، ٤ - الباطِنُ
INSERT INTO "names" VALUES(3,'الظاهر','الظَّاهِرُ','الذي ليس فوقه شيء، العالي فوق خلقه بقهره وعلوه','١ - الأوَّلُ ، ٢ - الآخِرُ، ٣ - الظَّاهِرُ، ٤ - الباطِنُ
INSERT INTO "names" VALUES(4,'الباطن','الباطِنُ','الذي ليس دونه شيء، المحتجب عن الأبصار العالم بخفايا الأمور','١ - الأوَّلُ ، ٢ - الآخِرُ، ٣ - الظَّاهِرُ، ٤ - الباطِنُ
INSERT INTO "names" VALUES(5,'العلي','العَلِيُّ','الرفيع فوق خلقه بقدرته وقهره وعلو ذاته','٥ - العَلِيُّ، ٦ - الأعْلَى، ٧ - الْمُتَعَالِقال اللَّه تعالى: {وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ} ،وقال تعالى: {سَبِّحِ اسْمَ رَبِّكَالأَعْلَى} ، وقال تعالى: {عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ} ،وذلك دالّ على أن جميع معاني العلوّ ثابتة للَّه من كل وجه.فله علوّ الذات؛ فإنه فوق المخلوقات، وعلى العرش استوى: أي علا، وارتفع.وله علوّ القدر: وهو علوّ صفاته وعظمتها، فلا يماثله صفة مخلوق، بل لا يقدر الخلائق كلهم أن
INSERT INTO "names" VALUES(6,'الأعلى','الأعْلَى','الذي علا على كل شيء بذاته وصفاته فلا أعلى منه','٥ - العَلِيُّ، ٦ - الأعْلَى، ٧ - الْمُتَعَالِقال اللَّه تعالى: {وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ} ،وقال تعالى: {سَبِّحِ اسْمَ رَبِّكَالأَعْلَى} ، وقال تعالى: {عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ} ،وذلك دالّ على أن جميع معاني العلوّ ثابتة للَّه من كل وجه.فله علوّ الذات؛ فإنه فوق المخلوقات، وعلى العرش استوى: أي علا، وارتفع.وله علوّ القدر: وهو علوّ صفاته وعظمتها، فلا يماثله صفة مخلوق، بل لا يقدر الخلائق كلهم أن
INSERT INTO "names" VALUES(7,'المتعال','الْمُتَعَالِ','المتنزه عن كل سوء ونقص ومماثلة للمخلوقات','٥ - العَلِيُّ، ٦ - الأعْلَى، ٧ - الْمُتَعَالِقال اللَّه تعالى: {وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ} ،وقال تعالى: {سَبِّحِ اسْمَ رَبِّكَالأَعْلَى} ، وقال تعالى: {عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ} ،وذلك دالّ على أن جميع معاني العلوّ ثابتة للَّه من كل وجه.فله علوّ الذات؛ فإنه فوق المخلوقات، وعلى العرش استوى: أي علا، وارتفع.وله علوّ القدر: وهو علوّ صفاته وعظمتها، فلا يماثله صفة مخلوق، بل لا يقدر الخلائق كلهم أن
INSERT INTO "names" VALUES(8,'العظيم','العَظِيمُ','الذي كملت عظمته في ذاته وصفاته وأفعاله','٨ - العَظِيمُقال اللَّه تعالى: {وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ} .
INSERT INTO "names" VALUES(9,'المجيد','المَجِيدُ','الواسع في المجد والعظمة والإحسان إلى خلقه','٩ - المَجِيدُ«المجيد» الذي له المجد العظيم، والمجد هو عظمة الصفات وسعتها، فكل وصف من أوصافه عظيم شأنه: فهو العليم الكامل في علمه، الرّحيم الذي وسعت رحمته كل شيء، القدير الذي لا يعجزه شيء، الحليم
INSERT INTO "names" VALUES(10,'الكبير','الْكَبِيرُ','الأكبر من كل شيء ذاتا وقدرا وقهرا','١٠ - الْكَبِيرُوهو - سبحانه وتعالى - الموصوف بصفات المجد، والكبرياء، والعظمة، والجلال، الذي هو أكبر من كل شيء، وأعظم من كل شيء، وأجل وأعلى.وله التعظيم والإجلال، في قلوب أوليائه وأصفيائه.قد ملئت قلوبهم من تعظيمه، وإجلاله، والخضوع له، والتذلل لكبريائه ، قال اللَّه تعالى:
INSERT INTO "names" VALUES(11,'السميع','السَّمِيعُ','الذي وسع سمعه كل شيء يسمع السر والنجوى','١١ - السَّمِيعُقال اللَّه تعالى: {وَكَانَ اللَّهُ سَمِيعًا بَصِيرًا} ، وكثيراً ما يقرن اللَّه بين صفة السمع والبصر، فكل من السمع والبصر محيط بجميع متعلقاته الظاهرة، والباطنة، فالسميع الذي أحاط سمعه بجميع المسموعات، فكل ما في العالم العلوي والسفلي من الأصوات يسمعها سرَّها وعلنها وكأنها لديه صوت واحد، لا تختلط عليه الأصوات، ولا تخفى عليه جميع اللغات، والقريب منها والبعيد، والسرّ والعلانية عنده سواء {سَوَاءٌ مِّنكُم مَّنْ أَسَرَّ الْقَوْلَ وَمَن جَهَرَ بِهِ وَمَنْ هُوَ مُسْتَخْفٍ بِاللَّيْلِ وَسَارِبٌ بِالنَّهَارِ} ، {قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي
INSERT INTO "names" VALUES(12,'البصير','البَصِيرُ','الذي يرى كل شيء وإن دق وصغر','١٢ - البصيرُالذي أحاط بصره بجميع المُبصِرات في أقطار الأرض والسموات، حتى أخفى ما يكون فيها، فيرى دبيب النملة السوداء على الصخرة الصّماء في الليلة الظلماء، وجميع أعضائها الباطنة والظاهرة، وسريان القوت في أعضائها الدقيقة، ويرى سريان المياه في أغصان الأشجار وعروقها، وجميع النباتات على اختلاف أنواعها وصغرها ودقَّتها، ويرى نياط عروق النملة والنحلة والبعوضة وأصغر من ذلك. فسبحان من تحيّرت العقول في عظمته، وسعة متعلقات صفاته، وكمال عظمته، ولطفه، وخبرته بالغيب، والشهادة، والحاضر والغائب، ويرى خيانات الأعين، وتقلبات الأجفان، وحركات الجنان، قال تعالى: {الَّذِي يَرَاكَ حِينَ تَقُومُ * وَتَقَلُّبَكَ فِي السَاجِدِينَ * إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ} ، {يَعْلَمُ خَائِنَةَ الأَعْيُنِ وَمَا تُخْفِي الصُّدُورُ} ،
INSERT INTO "names" VALUES(13,'العليم','العَلِيمُ','المحيط علمه بكل شيء ظاهر وباطن','١٣ - العَلِيمُ، ١٤ - الخَبِيرُقال اللَّه تعالى: {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ} . {إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ} .فهو العليم المحيط علمه بكل شيء: بالواجبات، والممتنعات، والممكنات، فيعلم تعالى نفسه الكريمة، ونعوته المقدسة، وأوصافه العظيمة، وهي الواجبات التي لا يمكن إلا وجودها، ويعلم الممتنعات حال امتناعها، ويعلم ما يترتّب على وجودها لو وُجدت. كما قال تعالى: {لَوْ كَانَ فِيهِمَا آلهَةٌ إِلاّ اللَّهُ لَفَسَدَتَا} . وقال تعالى: {مَا اتَّخَذَ الَّهُ مِن
INSERT INTO "names" VALUES(14,'الخبير','الخَبِيرُ','العالم ببواطن الأمور ودقائقها وخفاياها','١٣ - العَلِيمُ، ١٤ - الخَبِيرُقال اللَّه تعالى: {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ} . {إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ} .فهو العليم المحيط علمه بكل شيء: بالواجبات، والممتنعات، والممكنات، فيعلم تعالى نفسه الكريمة، ونعوته المقدسة، وأوصافه العظيمة، وهي الواجبات التي لا يمكن إلا وجودها، ويعلم الممتنعات حال امتناعها، ويعلم ما يترتّب على وجودها لو وُجدت. كما قال تعالى: {لَوْ كَانَ فِيهِمَا آلهَةٌ إِلاّ اللَّهُ لَفَسَدَتَا} . وقال تعالى: {مَا اتَّخَذَ الَّهُ مِن
INSERT INTO "names" VALUES(15,'الحميد','الحَمِيدُ','المستحق للحمد والثناء في كل حال','١٥ - الحَميدُقال اللَّه تعالى: {يَا أَيُّهَا النَّاسُ أَنتُمُ الْفُقَرَاءُ إِلَى اللَّهِ وَاللَّهُ هُوَ الْغَنِيُّ الْحَمِيدُ} .وذكر ابن القيم - رحمه الله - أن اللَّه حميد من وجهين:أحدهما: أنّ جميع المخلوقات ناطقة بحمده، فكل حمد وقع من أهل السموات والأرض الأوّلين منهم والآخرين، وكل حمد يقع منهم في الدنيا والآخرة، وكل حمد لم يقع منهم بل كان مفروضاً ومقدّراً حيثما تسلسسلت الأزمان واتصلت الأوقات، حمداً يملأ الوجود كله العالم العلوي ولسفلي، ويملأ نظير
INSERT INTO "names" VALUES(16,'العزيز','العَزيزُ','الغالب الذي لا يقهر ولا يغلب','١٦ - العَزيزُ،١٧ - القَدِيرُ،١٨ - القَادِرُ،١٩ - المُقتَدِرُ،٢٠ - القوِيُّ،٢١ - المَتِينُهذه الأسماء العظيمة معانيها متقاربة، فهو تعالى كامل القوة، عظيم القدرة، شامل العزّة {إِنَّ العِزَّةَ لِلَّهِ جَمِيعًا} ، وقال تعالى: {إِنَّ رَبَّكَ هُوَ الْقَوِيُّ الْعَزِيزُ} ، فمعاني العزة الثلاثة كلها كاملة للَّه العظيم:١ - عزّة القوة الدالّ عليها من أسمائه القوي المتين، وهي وصفه العظيم الذي لا تُنسَب إليه قوة المخلوقات وإنْ عَظُمَتْ. قال اللَّه تعالى: {إِنَّ اللَّه هُوَ
INSERT INTO "names" VALUES(17,'القدير','القَدِيرُ','الكامل القدرة الذي لا يعجزه شيء','١٦ - العَزيزُ،١٧ - القَدِيرُ،١٨ - القَادِرُ،١٩ - المُقتَدِرُ،٢٠ - القوِيُّ،٢١ - المَتِينُهذه الأسماء العظيمة معانيها متقاربة، فهو تعالى كامل القوة، عظيم القدرة، شامل العزّة {إِنَّ العِزَّةَ لِلَّهِ جَمِيعًا} ، وقال تعالى: {إِنَّ رَبَّكَ هُوَ الْقَوِيُّ الْعَزِيزُ} ، فمعاني العزة الثلاثة كلها كاملة للَّه العظيم:١ - عزّة القوة الدالّ عليها من أسمائه القوي المتين، وهي وصفه العظيم الذي لا تُنسَب إليه قوة المخلوقات وإنْ عَظُمَتْ. قال اللَّه تعالى: {إِنَّ اللَّه هُوَ
INSERT INTO "names" VALUES(18,'القادر','القَادِرُ','المتصف بالقدرة التامة على كل شيء','١٦ - العَزيزُ،١٧ - القَدِيرُ،١٨ - القَادِرُ،١٩ - المُقتَدِرُ،٢٠ - القوِيُّ،٢١ - المَتِينُهذه الأسماء العظيمة معانيها متقاربة، فهو تعالى كامل القوة، عظيم القدرة، شامل العزّة {إِنَّ العِزَّةَ لِلَّهِ جَمِيعًا} ، وقال تعالى: {إِنَّ رَبَّكَ هُوَ الْقَوِيُّ الْعَزِيزُ} ، فمعاني العزة الثلاثة كلها كاملة للَّه العظيم:١ - عزّة القوة الدالّ عليها من أسمائه القوي المتين، وهي وصفه العظيم الذي لا تُنسَب إليه قوة المخلوقات وإنْ عَظُمَتْ. قال اللَّه تعالى: {إِنَّ اللَّه هُوَ
