INSERT INTO "names" VALUES(20,'القوي','القوِيُّ','الكامل القوة الذي لا يعجزه شيء','١٦ - العَزيزُ،١٧ - القَدِيرُ،١٨ - القَادِرُ،١٩ - المُقتَدِرُ،٢٠ - القوِيُّ،٢١ - المَتِينُهذه الأسماء العظيمة معانيها متقاربة، فهو تعالى كامل القوة، عظيم القدرة، شامل العزّة {إِنَّ العِزَّةَ لِلَّهِ جَمِيعًا} ، وقال تعالى: {إِنَّ رَبَّكَ هُوَ الْقَوِيُّ الْعَزِيزُ} ، فمعاني العزة الثلاثة كلها كاملة للَّه العظيم:١ - عزّة القوة الدالّ عليها من أسمائه القوي المتين، وهي وصفه العظيم الذي لا تُنسَب إليه قوة المخلوقات وإنْ عَظُمَتْ. قال اللَّه تعالى: {إِنَّ اللَّه هُوَ
INSERT INTO "names" VALUES(21,'المتين','المَتِينُ','شديد القوة الذي لا يلحقه تعب ولا نصب','١٦ - العَزيزُ،١٧ - القَدِيرُ،١٨ - القَادِرُ،١٩ - المُقتَدِرُ،٢٠ - القوِيُّ،٢١ - المَتِينُهذه الأسماء العظيمة معانيها متقاربة، فهو تعالى كامل القوة، عظيم القدرة، شامل العزّة {إِنَّ العِزَّةَ لِلَّهِ جَمِيعًا} ، وقال تعالى: {إِنَّ رَبَّكَ هُوَ الْقَوِيُّ الْعَزِيزُ} ، فمعاني العزة الثلاثة كلها كاملة للَّه العظيم:١ - عزّة القوة الدالّ عليها من أسمائه القوي المتين، وهي وصفه العظيم الذي لا تُنسَب إليه قوة المخلوقات وإنْ عَظُمَتْ. قال اللَّه تعالى: {إِنَّ اللَّه هُوَ
INSERT INTO "names" VALUES(22,'الغني','الغَنِيُّ','المستغني عن كل ما سواه المفتقر إليه كل شيء','٢٢ - الغَنِيُّقال اللَّه تعالى: {وَأَنَّهُ هُوَ أَغْنَى وَأَقْنَى} . وقال اللَّه تعالى: {يَا أَيُّهَا النَّاسُ أَنتُمُ الْفُقَرَاءُ إِلَى اللَّهِ وَاللَّهُ هُوَ الْغَنِيُّ الْحَمِيدُ} . فهو تعالى (الغني) الذي له الغنى التام المطلق من كل الوجوه لكماله وكمال صفاته التي لا يتطرق إليها نقص بوجه من الوجوه، ولا يمكن أن يكون إلا غنياً، فإنّ غناه من لوازم ذاته، كما لا يكون إلا محسناً، جواداً، براً، رحيماً كريماً، والمخلوقات بأسرها لا تستغني عنه في حال من أحوالها، فهي مفتقرة إليه في إيجادها، وفي بقائها، وفي كل ما تحتاجه أو تضطر إليه، ومن سعة غناه أن خزائن السموات والأرض والرحمة بيده، وأن جوده على خلقه متواصل في جميع اللحظات والأوقات، وأن يده سحاء الليل والنهار، وخيره على الخلق
INSERT INTO "names" VALUES(23,'الحكيم','الحَكِيمُ','الذي يضع الأمور مواضعها بحكمته البالغة','٢٣ - الحَكِيمُقال اللَّه تعالى: {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ} .وهو تعالى «الحكيم» الموصوف بكمال الحكمة وبكمال الحكم بين المخلوقات، فالحكيم هو واسع العلم والاطّلاع على مبادئ الأمور وعواقبها، واسع الحمد، تام القدرة، غزير الرحمة، فهو الذي يضع الأشياء مواضعها، وينزلها منازلها اللائقة بها في خلْقه وأمره، فلا يتوجه إليه سؤال، ولا يقدح في حكمته مقال.
INSERT INTO "names" VALUES(24,'الحليم','الْحَلِيمُ','الذي لا يعجل بالعقوبة ويمهل العصاة للتوبة','٢٤ - الْحَلِيمُقال اللَّه تعالى: {وَاعْلَمُواْ أَنَّ اللَّهَ يَعْلَمُ مَا فِي أَنفُسِكُمْ فَاحْذَرُوهُ وَاعْلَمُواْ أَنَّ اللَّهَ غَفُورٌ حَلِيمٌ} .الذي يَدِرُّ على خلقه، النعم الظاهرة والباطنة، مع معاصيهم وكثرة زلاَّتهم، فيحلم عن مقابلة العاصين
INSERT INTO "names" VALUES(25,'العفو','العَفُوُّ','الذي يمحو السيئات ويتجاوز عن المعاصي','٢٥ - العَفُوُّ، ٢٦ - الغَفُورُ، ٢٧ - الغَفَّارُقال اللَّه تعالى: {إِنَّ اللَّه لَعَفُوٌّ غَفُورٌ} .الذي لم يزل، ولا يزال بالعفو معروفاً، وبالغفران والصفح عن عباده، موصوفاً.كل أحد مضطر إلى عفوه ومغفرته كما هو مضطر إلى رحمته وكرمه.وقد وعد بالمغفرة والعفو، لمن أتى بأسبابها، قال تعالى : {وَإِنِّي لَغَفَّارٌ لِّمَن تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى} .والعفوّ هو الذي له العفو الشامل الذي وسع ما يصدر من عباده من الذنوب، ولا سيما إذا أتوا لما يسبب العفو عنهم من الاستغفار، والتوبة، والإيمان، والأعمال الصلحة فهو سبحانه يقبل التوبة عن عباده
INSERT INTO "names" VALUES(26,'الغفور','الغَفُورُ','الذي يستر الذنوب ويغفرها مهما عظمت','٢٥ - العَفُوُّ، ٢٦ - الغَفُورُ، ٢٧ - الغَفَّارُقال اللَّه تعالى: {إِنَّ اللَّه لَعَفُوٌّ غَفُورٌ} .الذي لم يزل، ولا يزال بالعفو معروفاً، وبالغفران والصفح عن عباده، موصوفاً.كل أحد مضطر إلى عفوه ومغفرته كما هو مضطر إلى رحمته وكرمه.وقد وعد بالمغفرة والعفو، لمن أتى بأسبابها، قال تعالى : {وَإِنِّي لَغَفَّارٌ لِّمَن تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى} .والعفوّ هو الذي له العفو الشامل الذي وسع ما يصدر من عباده من الذنوب، ولا سيما إذا أتوا لما يسبب العفو عنهم من الاستغفار، والتوبة، والإيمان، والأعمال الصلحة فهو سبحانه يقبل التوبة عن عباده
INSERT INTO "names" VALUES(27,'الغفار','الغَفَّارُ','الذي يغفر الذنوب مرارا وتكرارا لمن تاب','٢٥ - العَفُوُّ، ٢٦ - الغَفُورُ، ٢٧ - الغَفَّارُقال اللَّه تعالى: {إِنَّ اللَّه لَعَفُوٌّ غَفُورٌ} .الذي لم يزل، ولا يزال بالعفو معروفاً، وبالغفران والصفح عن عباده، موصوفاً.كل أحد مضطر إلى عفوه ومغفرته كما هو مضطر إلى رحمته وكرمه.وقد وعد بالمغفرة والعفو، لمن أتى بأسبابها، قال تعالى : {وَإِنِّي لَغَفَّارٌ لِّمَن تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى} .والعفوّ هو الذي له العفو الشامل الذي وسع ما يصدر من عباده من الذنوب، ولا سيما إذا أتوا لما يسبب العفو عنهم من الاستغفار، والتوبة، والإيمان، والأعمال الصلحة فهو سبحانه يقبل التوبة عن عباده
INSERT INTO "names" VALUES(28,'التواب','التَّوَّابُ','الذي يقبل التوبة من عباده ويعفو عنهم','٢٨ - التَّوَّابُقال اللَّه تعالى: {أَلَمْ يَعْلَمُواْ أَنَّ اللَّهَ هُوَ يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ وَيَأْخُذُ الصَّدَقَاتِ وَأَنَّ اللَّهَ هُوَ التَّوَّابُ الرَّحِيمُ} .«التَّوَّابُ» الذي لم يزل يتوب على التائبين، ويغفر ذنوب المنيبين، فكل من تاب إلى اللَّه توبة نصوحاً، تاب اللَّه عليه.فهو التائب على التائبين: أولاً بتوفيقهم للتوبة والإقبال بقلوبهم إليه. وهو التائب عليهم بعد توبتهم، قبولاً لها، وعفواً عن خطاياهم .
INSERT INTO "names" VALUES(29,'الرقيب','الرَّقيبُ','المطلع على كل شيء الحافظ له','٢٩ - الرَّقيبُالرقيب: المطَّلع على ما أكنَّته الصدور، القائم على كل نفس بما كسبت. قال اللَّه تعالى: {إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا} .
INSERT INTO "names" VALUES(30,'الشهيد','الشَّهيدُ','الحاضر الذي لا يغيب عنه شيء','٣٠ - الشَّهيدُالشهيد: أي المطَّلع على جميع الأشياء. سمع جميع الأصوات، خفيّها وجليها. وأبصر جميع الموجودات، دقيقها وجليلها، صغيرها وكبيرها، وأحاط علمه بكل شيء، الذي شهد لعباده، وعلى عباده، بما عملوه .قال الشيخ عبد الرحمن السعدي - رحمه الله - تعالى: «الرقيب» و «الشهيد» مترادفان، وكلاهما يدلُّ على إحاطة سمع اللَّه بالمسموعات، وبصره بالمبصرات، وعلمِه بجميع المعلومات الجليّة والخفية، وهو الرقيب على ما دار في الخواطر، وما تحركت به اللواحظ، ومن باب أولى
INSERT INTO "names" VALUES(31,'الحفيظ','الحَفِيظُ','الحافظ لكل شيء من كل سوء','٣١ - الحَفِيظُقال اللَّه تعالى: {إِنَّ رَبِّي عَلَىَ كُلِّ شَيْءٍحَفِيظٌ}  «للحفيظ» معنيان:المعنى الأول: أنه قد حفظ على عباده ما عملوه من خير وشر وطاعة ومعصية؛ فإن علمه محيط بجميع أعمالهم ظاهرها وباطنها، وقد كتب ذلك في اللوح المحفوظ، ووكَّل بالعباد ملائكة كراماً كاتبين «يَعْلَمُونَ مَا تَفْعَلُونَ» ، فهذا المعنى من حفظه يقتضي إحاطة علم اللَّه بأحوال العباد كلها ظاهرها وباطنها وكتابتها في اللوح المحفوظ وفي الصحف التي في أيدي الملائكة، وعلمه بمقاديرها، وكمالها، ونقصها، ومقادير جزائها في الثواب والعقاب ثم مجازاته عليها بفضله وعدله.والمعنى الثاني: من معنيي «الحفيظ» أنه تعالى
INSERT INTO "names" VALUES(32,'اللطيف','اللَّطِيفُ','الرفيق بعباده المحسن إليهم في خفاء ولطف','٣٢ - اللَّطِيفُقال اللَّه تعالى: {اللَّهُ لَطِيفٌ بِعِبَادِهِ يَرْزُقُ مَن يَشَاءُ
INSERT INTO "names" VALUES(33,'القريب','القَرِيبُ','الذي قرب من عباده بعلمه وإجابته لدعائهم','٣٣ - القَرِيبُقال اللَّه تعالى: {هُوَ أَنَأَكُم مِّنَ الأَرْضِ وَاسْتَعْمَرَكُمْ فِيهَا فَاسْتَغْفِرُوهُ ثُمَّ تُوبُواْ إِلَيْهِ إِنَّ رَبِّي قَرِيبٌ مُّجِيبٌ} .من أسماء اللَّه تعالى: «القريب»، وقربه نوعان:النوع الأول: قرب عام وهو إحاطة علمه بجميع الأشياء، وهو أقرب إلى الإنسان من حبل الوريد، وهو بمعنى المعية العامة.النوع الثاني: وقرب خاص بالداعين والعابدين المحبين، وهو قرب يقتضي المحبة، والنصرة، والتأييد
INSERT INTO "names" VALUES(34,'المجيب','المُجِيبُ','الذي يجيب دعاء من دعاه ويعطي من سأله','٣٤ - المُجِيبُمن أسماء اللَّه تعالى «المجيب» لدعوة الداعين وسؤال السائلين وعبادة المستجيبين، وإجابته نوعان:النوع الأول: إجابة عامة لكل من دعاه: دعاء عبادة، أو دعاء مسألة، قال اللَّه تعالى: {وَقَالَ رَبُّكُمُ
INSERT INTO "names" VALUES(35,'الودود','الوَدُودُ','المحب لعباده الصالحين المحبوب لهم','٣٥ - الوَدُودُقال تعالى: {وَاسْتَغْفِرُواْ رَبَّكُمْ ثُمَّ تُوبُواْ إِلَيْهِ إِنَّ رَبِّي رَحِيمٌ وَدُودٌ} . وقال تعالى: {وَهُوَ الْغَفُورُ الْوَدُودُ} ، والودّ مأخوذ من الوُدّ بضم الواو بمعنى خالص المحبة، فالودود هو المحب المحبوب بمعنى وادّ مودود، فهو الواد لأنبيائه، وملائكته، وعباده المؤمنين، وهو المحبوب لهم، بل لا شيء أحب إليهم منه، ولا تعادل محبة اللَّه من أصفيائه محبة أخرى، لا في أصلها، ولا في كيفيتها، ولا في متعلّقاتها، وهذا هو الفرض والواجب أن تكون محبة اللَّه في قلب العبد سابقة لكل محبة، غالبة لكل محبة، ويتعيّن أن تكون بقية المحابّ تبعاً لها.ومحبة اللَّه هي روح الأعمال، وجميع العبودية الظاهرة والباطنة ناشئة عن محبة اللَّه.
INSERT INTO "names" VALUES(36,'الشاكر','الشَّاكِرُ','الذي يجازي على العمل القليل بالأجر الكثير','٣٦ - الشَّاكِرُ، ٣٧ - الشَّكُورُقال اللَّه تعالى: {وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ اللَّهَ شَاكِرٌ عَلِيمٌ} ، وقال تعالى: {إِن تُقْرِضُوا اللَّهَ قَرْضاً حَسَناً يُضَاعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ وَاللَّهُ شَكُورٌحَلِيمٌ} ، {وَكَانَ اللَّهُ شَاكِراً عَلِيماً} .
INSERT INTO "names" VALUES(37,'الشكور','الشَّكُورُ','الذي يضاعف الثواب ويشكر القليل من العمل','٣٦ - الشَّاكِرُ، ٣٧ - الشَّكُورُقال اللَّه تعالى: {وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ اللَّهَ شَاكِرٌ عَلِيمٌ} ، وقال تعالى: {إِن تُقْرِضُوا اللَّهَ قَرْضاً حَسَناً يُضَاعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ وَاللَّهُ شَكُورٌحَلِيمٌ} ، {وَكَانَ اللَّهُ شَاكِراً عَلِيماً} .
INSERT INTO "names" VALUES(38,'السيد','السَّيِّدُ','الذي كمل في سؤدده وشرفه وملكه','٣٨ - السَّيِّدُ، ٣٩ - الصَّمَدُقال اللَّه تعالى: {قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ} .وقال النبي - صلى الله عليه وسلم -: «السَّيِّدُ اللَّه تبارك وتعالى»  و «السيد» يطلق على الرّب، والمالك، والشريف، والفاضل، والكريم، والحليم، والرئيس، والزوج، ومُتَحَمِّل أذى قومه، واللَّه - عز وجل - هو السيد الذي يملك نواصي الخلق ويتولاهم، فالسؤدد كله حقيقة للَّه والخلق كلهم عبيده.
INSERT INTO "names" VALUES(39,'الصمد','الصَّمَدُ','الذي تقصده الخلائق في حوائجها لكماله','٣٨ - السَّيِّدُ، ٣٩ - الصَّمَدُقال اللَّه تعالى: {قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ} .وقال النبي - صلى الله عليه وسلم -: «السَّيِّدُ اللَّه تبارك وتعالى»  و «السيد» يطلق على الرّب، والمالك، والشريف، والفاضل، والكريم، والحليم، والرئيس، والزوج، ومُتَحَمِّل أذى قومه، واللَّه - عز وجل - هو السيد الذي يملك نواصي الخلق ويتولاهم، فالسؤدد كله حقيقة للَّه والخلق كلهم عبيده.
INSERT INTO "names" VALUES(40,'القاهر','القَاهِرُ','الغالب لكل شيء بقدرته','٤٠ - القَاهِرُ، ٤١ - القَهَّارُقال اللَّه تعالى: {قُلِ اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ الْوَاحِدُ الْقَهَّارُ} . وقال تعالى: {يَوْمَ هُم بَارِزُونَ لا يَخْفَى عَلَى اللَّهِ مِنْهُمْ شَيْءٌ لِّمَنِ الْمُلْكُ الْيَوْمَ لِلَّهِ الْوَاحِدِ الْقَهَّارِ} . وقال - عز وجل -: {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ} .وهو الذي قهر جميع الكائنات، وذلّت له جميع
INSERT INTO "names" VALUES(41,'القهار','القَهَّارُ','الذي قهر كل شيء وخضع له كل موجود','٤٠ - القَاهِرُ، ٤١ - القَهَّارُقال اللَّه تعالى: {قُلِ اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ الْوَاحِدُ الْقَهَّارُ} . وقال تعالى: {يَوْمَ هُم بَارِزُونَ لا يَخْفَى عَلَى اللَّهِ مِنْهُمْ شَيْءٌ لِّمَنِ الْمُلْكُ الْيَوْمَ لِلَّهِ الْوَاحِدِ الْقَهَّارِ} . وقال - عز وجل -: {وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ} .وهو الذي قهر جميع الكائنات، وذلّت له جميع
INSERT INTO "names" VALUES(42,'الجبار','الجَبَّارُ','الذي يجبر الكسير ويغني الفقير ويقهر الجبابرة','٤٢ - الجَبَّارُقال اللَّه تعالى: {هُوَ اللَّهُ الَّذِي لا إِلَهَ إِلَّا هُوَ الْمَلِكُ الْقُدُّوسُ السَّلامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ} .
INSERT INTO "names" VALUES(43,'الحسيب','الحَسِيبُ','الكافي عباده المحاسب لهم على أعمالهم','٤٣ - الحَسِيبُقال اللَّه تعالى: {وَكَفَى بِاللَّهِ حَسِيبًا} ، وقال سبحانه: {أَلاَ لَهُ الْحُكْمُ وَهُوَ أَسْرَعُ الْحَاسِبِينَ} ، والحسيبُ:١ - هو الكافي للعباد جميع ما أهمّهم من أمر دينهم ودنياهم من حصول المنافع ودفع المضارّ.٢ - والحسيب بالمعنى الأخصّ هو الكافي لعبده المتَّقي المتوكِّل عليه كفاية خاصة يصلح بها دينه ودنياه.
INSERT INTO "names" VALUES(44,'الهادي','الْهَادِي','الذي يهدي من يشاء إلى الحق والصراط المستقيم','٤٤ - الْهَادِيقال اللَّه تعالى: {وَكَفَى بِرَبِّكَ هَادِيًاوَنَصِيرًا} . وقال تعالى: {وَإِنَّ اللَّهَ لَهَادِ الَّذِينَ آمَنُوا إِلَى صِرَاطٍ مُّسْتَقِيمٍ} .[الهادي] أي: الذين يهدي ويرشد عباده إلى جميع المنافع، وإلى دفع المضار، ويُعلِّمهم ما لا
INSERT INTO "names" VALUES(45,'الحكم','الحَكَمُ','الذي يحكم بين عباده بعدله ولا معقب لحكمه','٤٥ - الحَكَمُقال اللَّه تعالى: {فَاصْبِرُواْ حَتَّى يَحْكُمَ اللَّهُ بَيْنَنَا وَهُوَ خَيْرُ الْحَاكِمِينَ} ، وقال تعالى: {وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلاً لاَّ مُبَدِّلِ لِكَلِمَاتِهِ}  وقال تعالى: {إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالإِحْسَانِ} ، وقال النبي - صلى الله عليه وسلم -: «إن اللَّه هو الحكمُ وإليه الحكم» .وقال تعالى: {أَفَغَيْرَ اللَّهِ أَبْتَغِي حَكَمًا وَهُوَ الَّذِي
INSERT INTO "names" VALUES(46,'القدوس','القُدُّوسُ','المنزه عن كل نقص وعيب','٤٦ - القُدُّوسُ، ٤٧ - السَّلامُقال اللَّه تعالى: {هُوَ اللَّهُ الَّذِي لا إِلَهَ إِلا هُوَ الْمَلِكُ
INSERT INTO "names" VALUES(47,'السلام','السَّلامُ','السالم من كل عيب المسلم عباده من كل ظلم','٤٦ - القُدُّوسُ، ٤٧ - السَّلامُقال اللَّه تعالى: {هُوَ اللَّهُ الَّذِي لا إِلَهَ إِلا هُوَ الْمَلِكُ
INSERT INTO "names" VALUES(48,'البر','البَرُّ','المحسن إلى خلقه ببره ولطفه','٤٨ - البَرُّ، ٤٩ - الوَهَّابُقال اللَّه تعالى: {إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ} ، وقال سبحانه: {رَبَّنَا لاَ تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً إِنَّكَ أَنتَ الْوَهَّابُ} .من أسمائه تعالى: «البرّ الوهّاب» الذي شمل الكائنات بأسرها بِبِرِّهِ وهباته وكرمه، فهو مولى الجميل ودائم الإحسان وواسع المواهب، وصفُه البَرُّ وآثار هذا الوصف جميع النعم الظاهرة والباطنة، فلا يستغني مخلوق عن إحسانه وبِرِّه طرفة عين.وإحسانه عام وخاص:١ - فالعامّ المذكور في قوله: {رَبَّنَا وَسِعْتَ كُلَّ
INSERT INTO "names" VALUES(49,'الوهاب','الوَهَّابُ','كثير العطاء بلا عوض ولا سؤال','٤٨ - البَرُّ، ٤٩ - الوَهَّابُقال اللَّه تعالى: {إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ} ، وقال سبحانه: {رَبَّنَا لاَ تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً إِنَّكَ أَنتَ الْوَهَّابُ} .من أسمائه تعالى: «البرّ الوهّاب» الذي شمل الكائنات بأسرها بِبِرِّهِ وهباته وكرمه، فهو مولى الجميل ودائم الإحسان وواسع المواهب، وصفُه البَرُّ وآثار هذا الوصف جميع النعم الظاهرة والباطنة، فلا يستغني مخلوق عن إحسانه وبِرِّه طرفة عين.وإحسانه عام وخاص:١ - فالعامّ المذكور في قوله: {رَبَّنَا وَسِعْتَ كُلَّ
INSERT INTO "names" VALUES(50,'الرحمن','الرَّحْمَنُ','الذي وسعت رحمته كل شيء','٥٠ - الرَّحْمَنُ، ٥١ - الرَّحِيمُ، ٥٢ - الكَرِيمُ، ٥٣ - الأكْرَمُ، ٥٤ - الرَّءُوفُقال اللَّه تعالى: {الْحَمْدُ للَّهِ رَبِّ الْعَالَمينَ* لرَّحْمنِ
INSERT INTO "names" VALUES(51,'الرحيم','الرَّحِيمُ','المنعم على عباده المؤمنين برحمته الخاصة','٥٠ - الرَّحْمَنُ، ٥١ - الرَّحِيمُ، ٥٢ - الكَرِيمُ، ٥٣ - الأكْرَمُ، ٥٤ - الرَّءُوفُقال اللَّه تعالى: {الْحَمْدُ للَّهِ رَبِّ الْعَالَمينَ* لرَّحْمنِ
INSERT INTO "names" VALUES(52,'الكريم','الكَرِيمُ','كثير الخير والعطاء الذي لا ينفد','٥٠ - الرَّحْمَنُ، ٥١ - الرَّحِيمُ، ٥٢ - الكَرِيمُ، ٥٣ - الأكْرَمُ، ٥٤ - الرَّءُوفُقال اللَّه تعالى: {الْحَمْدُ للَّهِ رَبِّ الْعَالَمينَ* لرَّحْمنِ
INSERT INTO "names" VALUES(53,'الأكرم','الأكْرَمُ','الذي لا كريم يساويه في كرمه وفضله','٥٠ - الرَّحْمَنُ، ٥١ - الرَّحِيمُ، ٥٢ - الكَرِيمُ، ٥٣ - الأكْرَمُ، ٥٤ - الرَّءُوفُقال اللَّه تعالى: {الْحَمْدُ للَّهِ رَبِّ الْعَالَمينَ* لرَّحْمنِ
INSERT INTO "names" VALUES(54,'الرءوف','الرَّءُوفُ','شديد الرحمة بعباده','٥٠ - الرَّحْمَنُ، ٥١ - الرَّحِيمُ، ٥٢ - الكَرِيمُ، ٥٣ - الأكْرَمُ، ٥٤ - الرَّءُوفُقال اللَّه تعالى: {الْحَمْدُ للَّهِ رَبِّ الْعَالَمينَ* لرَّحْمنِ
INSERT INTO "names" VALUES(55,'الفتاح','الفَتَّاحُ','الذي يفتح أبواب الرحمة والرزق لعباده','٥٥ - الْفَتَّاحُقال اللَّه تعالى: {قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِالْحَقِّ وَهُوَ الْفَتَّاحُ الْعَلِيمُ} .الفاتح: الحاكم، والفتاح من أبنية المبالغة.فالفتّاح هو الحكم المحسن الجواد، وفَتْحهُ
INSERT INTO "names" VALUES(56,'الرزاق','الرَّزَّاقُ','المتكفل بأرزاق العباد جميعا','٥٦ - الرَّزَّاقُ، ٥٧ - الرَّازِقُوهو مبالغة من: رازق للدلالة على الكثرة، والرزاق من أسمائه سبحانه.قال تعالى: {إِنَّ اللَّهَ هُوَ الرَّزَّاقُ} ، {وَمَا مِن دَآبَّةٍ فِي الأَرْضِ إِلاَّ عَلَى اللَّهِ رِزْقُهَا} ، وقال النبي - صلى الله عليه وسلم -: «إنَّ اللَّه هوَ المسَعِّرُ القابضُ الباسطُ الرَّازِقُ»  ورزقه لعباده نوعان: عام، وخاص.١ - فالعام إيصاله لجميع الخليقة جميع ما
INSERT INTO "names" VALUES(57,'الرازق','الرَّازِقُ','الذي يرزق من يشاء ويقدر الأرزاق بحكمته','٥٦ - الرَّزَّاقُ، ٥٧ - الرَّازِقُوهو مبالغة من: رازق للدلالة على الكثرة، والرزاق من أسمائه سبحانه.قال تعالى: {إِنَّ اللَّهَ هُوَ الرَّزَّاقُ} ، {وَمَا مِن دَآبَّةٍ فِي الأَرْضِ إِلاَّ عَلَى اللَّهِ رِزْقُهَا} ، وقال النبي - صلى الله عليه وسلم -: «إنَّ اللَّه هوَ المسَعِّرُ القابضُ الباسطُ الرَّازِقُ»  ورزقه لعباده نوعان: عام، وخاص.١ - فالعام إيصاله لجميع الخليقة جميع ما
INSERT INTO "names" VALUES(58,'الحي','الحَيُّ','الذي له الحياة الكاملة الدائمة التي لا تزول','٥٨ - الْحَيُّ، ٥٩ - الْقَيُّومُقال اللَّه تعالى: {اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ} ، وقال سبحانه: {الم * اللَّهُ لا إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ} ، وقال - عز وجل -:
INSERT INTO "names" VALUES(59,'القيوم','الْقَيُّومُ','القائم بنفسه المقيم لغيره الغني عن كل شيء','٥٨ - الْحَيُّ، ٥٩ - الْقَيُّومُقال اللَّه تعالى: {اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ} ، وقال سبحانه: {الم * اللَّهُ لا إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ} ، وقال - عز وجل -:
INSERT INTO "names" VALUES(60,'نور السموات والأرض','نُورُ السَّمَوَاتِ وَالأَرْضِ','الذي نور السماوات والأرض وهدى أهلها','٦٠ - نُورُ السَّمَوَاتِ وَالأَرْضِ قال تعالى: {اللَّهُ نُورُ السَّمَوَاتِ وَالأَرْضِ مَثَلُ نُورِهِ كَمِشْكَاةٍ فِيهَا مِصْبَاحٌ الْمِصْبَاحُ فِي زُجَاجَةٍ الزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّيٌّ يُوقَدُ مِن شَجَرَةٍ مُّبَارَكَةٍ زَيْتُونِةٍ لا شَرْقِيَّةٍ وَلا غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِيءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ نُّورٌ عَلَى نُورٍ يَهْدِي اللَّهُ لِنُورِهِ مَن يَشَاء} ، وقال النبي - صلى الله عليه وسلم -: «اللَّهم لك الحمد، أنت نور السموات والأرض ومن فيهن ... »  الحديث.وقال - صلى الله عليه وسلم -: «إن اللَّه - عز وجل - لا ينام، ولا ينبغي له أن
INSERT INTO "names" VALUES(61,'الرب','الرَّبُّ','المالك المتصرف المربي خلقه بالنعم','٦١ - الرَّبُّقال اللَّه تعالى: {قُلْ أَغَيْرَ اللَّهِ أَبْغِي رَبًّا وَهُوَ رَبُّ كُلِّ شَيْءٍ} .اللَّه - عز وجل - هو: المُرَبِّي جميع عباده، بالتدبير، وأصناف النعم. وأخص من هذا، تربيته لأصفيائه، بإصلاح قلوبهم، وأرواحهم وأخلاقهم، ولهذا كثر دعاؤهم له بهذا الاسم الجليل؛ لأنهم يطلبون منه هذه التربية الخاصة.[٦٢ - الله]واللَّه - عز وجل - هو المألوه المعبود، ذو الألوهية والعبودية على خلقه أجمعين، لما اتصف به من
INSERT INTO "names" VALUES(62,'الله','اللَّهُ','المألوه المعبود وحده المستحق للعبادة','٦١ - الرَّبُّقال اللَّه تعالى: {قُلْ أَغَيْرَ اللَّهِ أَبْغِي رَبًّا وَهُوَ رَبُّ كُلِّ شَيْءٍ} .اللَّه - عز وجل - هو: المُرَبِّي جميع عباده، بالتدبير، وأصناف النعم. وأخص من هذا، تربيته لأصفيائه، بإصلاح قلوبهم، وأرواحهم وأخلاقهم، ولهذا كثر دعاؤهم له بهذا الاسم الجليل؛ لأنهم يطلبون منه هذه التربية الخاصة.[٦٢ - الله]واللَّه - عز وجل - هو المألوه المعبود، ذو الألوهية والعبودية على خلقه أجمعين، لما اتصف به من
INSERT INTO "names" VALUES(63,'الملك','المَلِكُ','الذي له الملك كله يتصرف فيه كيف يشاء','٦٣ - المَلِكُ، ٦٤ - المَلِيكُ، ٦٥ - مَالِكُ المُلْكِقال اللَّه تعالى: {فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ لا إِلَهَ إِلاّ هُوَ رَبُّ الْعَرْشِ الْكَرِيمِ} .وقال تعالى: {فِي مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍمُّقْتَدِرٍ} ، {قُلِ اللَّهمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَن تَشَاءُ وَتَنزِعُ الْمُلْكَ مِمَّن تَشَاءُ وَتُعِزُّ مَن تَشَاءُ وَتُذِلُّ مَن
INSERT INTO "names" VALUES(64,'المليك','المَلِيكُ','المالك العظيم الملك الواسع التصرف','٦٣ - المَلِكُ، ٦٤ - المَلِيكُ، ٦٥ - مَالِكُ المُلْكِقال اللَّه تعالى: {فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ لا إِلَهَ إِلاّ هُوَ رَبُّ الْعَرْشِ الْكَرِيمِ} .وقال تعالى: {فِي مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍمُّقْتَدِرٍ} ، {قُلِ اللَّهمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَن تَشَاءُ وَتَنزِعُ الْمُلْكَ مِمَّن تَشَاءُ وَتُعِزُّ مَن تَشَاءُ وَتُذِلُّ مَن
INSERT INTO "names" VALUES(65,'مالك الملك','مَالِكُ المُلْكِ','الذي يؤتي الملك من يشاء وينزعه ممن يشاء','٦٣ - المَلِكُ، ٦٤ - المَلِيكُ، ٦٥ - مَالِكُ المُلْكِقال اللَّه تعالى: {فَتَعَالَى اللَّهُ الْمَلِكُ الْحَقُّ لا إِلَهَ إِلاّ هُوَ رَبُّ الْعَرْشِ الْكَرِيمِ} .وقال تعالى: {فِي مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍمُّقْتَدِرٍ} ، {قُلِ اللَّهمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَن تَشَاءُ وَتَنزِعُ الْمُلْكَ مِمَّن تَشَاءُ وَتُعِزُّ مَن تَشَاءُ وَتُذِلُّ مَن
INSERT INTO "names" VALUES(66,'الواحد','الوَاحِدُ','المتفرد بالألوهية والربوبية والأسماء والصفات','٦٦ - الوَاحِدُ، ٦٧ - الأحَدُقال اللَّه تعالى: {قُلْ هُوَ اللَّهُ أَحَدٌ} ، وقال سبحانه: {قُلِ اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ الْوَاحِدُ الْقَهَّارُ} .وهو الذي توحّد بجميع الكمالات، بحيث لا يشاركه فيها مشارك.
INSERT INTO "names" VALUES(67,'الأحد','الأحَدُ','المتفرد في ذاته وصفاته لا نظير له','٦٦ - الوَاحِدُ، ٦٧ - الأحَدُقال اللَّه تعالى: {قُلْ هُوَ اللَّهُ أَحَدٌ} ، وقال سبحانه: {قُلِ اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ الْوَاحِدُ الْقَهَّارُ} .وهو الذي توحّد بجميع الكمالات، بحيث لا يشاركه فيها مشارك.
INSERT INTO "names" VALUES(68,'المتكبر','المُتَكَبِّرُ','المتعالي عن كل نقص المتفرد بالعظمة والكبرياء','٦٨ - المُتَكَبِّرُقال اللَّه تعالى: {هُوَ اللَّهُ الَّذِي لا إِلَهَ إِلاّ هُوَ الْمَلِكُ الْقُدُّوسُ السَّلامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ سُبْحَانَ اللَّهِ عَمَّا يُشْرِكُونَ} .فهو سبحانه المتكبر عن السوء، والنقص والعيوب، لعظمته وكبريائه.٦٩ - الْخَالِقُ،٧٠ - البَارِئُ، ٧١ - المُصَوِّرُ، ٧٢ - الْخَلاَّقُقال تعالى: {هُوَ اللَّهُ الخَالِقُ الْبَارِئُ المُصَوِّرُ لَهُ الأَسْمَاءُ الْحُسْنَى} . {إِنَّ رَبَّكَ هُوَ الْخَلاَّقُ الْعَلِيمُ} .الذي خلق جميع الموجودات وبرأها، وسوّاها
INSERT INTO "names" VALUES(69,'الخالق','الْخَالِقُ','الذي أوجد المخلوقات من العدم بقدرته','٦٨ - المُتَكَبِّرُقال اللَّه تعالى: {هُوَ اللَّهُ الَّذِي لا إِلَهَ إِلاّ هُوَ الْمَلِكُ الْقُدُّوسُ السَّلامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ سُبْحَانَ اللَّهِ عَمَّا يُشْرِكُونَ} .فهو سبحانه المتكبر عن السوء، والنقص والعيوب، لعظمته وكبريائه.٦٩ - الْخَالِقُ،٧٠ - البَارِئُ، ٧١ - المُصَوِّرُ، ٧٢ - الْخَلاَّقُقال تعالى: {هُوَ اللَّهُ الخَالِقُ الْبَارِئُ المُصَوِّرُ لَهُ الأَسْمَاءُ الْحُسْنَى} . {إِنَّ رَبَّكَ هُوَ الْخَلاَّقُ الْعَلِيمُ} .الذي خلق جميع الموجودات وبرأها، وسوّاها
INSERT INTO "names" VALUES(70,'البارئ','البَارِئُ','الذي برأ الخلق وميز بعضهم من بعض','٦٨ - المُتَكَبِّرُقال اللَّه تعالى: {هُوَ اللَّهُ الَّذِي لا إِلَهَ إِلاّ هُوَ الْمَلِكُ الْقُدُّوسُ السَّلامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ سُبْحَانَ اللَّهِ عَمَّا يُشْرِكُونَ} .فهو سبحانه المتكبر عن السوء، والنقص والعيوب، لعظمته وكبريائه.٦٩ - الْخَالِقُ،٧٠ - البَارِئُ، ٧١ - المُصَوِّرُ، ٧٢ - الْخَلاَّقُقال تعالى: {هُوَ اللَّهُ الخَالِقُ الْبَارِئُ المُصَوِّرُ لَهُ الأَسْمَاءُ الْحُسْنَى} . {إِنَّ رَبَّكَ هُوَ الْخَلاَّقُ الْعَلِيمُ} .الذي خلق جميع الموجودات وبرأها، وسوّاها
INSERT INTO "names" VALUES(71,'المصور','المُصَوِّرُ','الذي صور المخلوقات كيف شاء بحكمته','٦٨ - المُتَكَبِّرُقال اللَّه تعالى: {هُوَ اللَّهُ الَّذِي لا إِلَهَ إِلاّ هُوَ الْمَلِكُ الْقُدُّوسُ السَّلامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ سُبْحَانَ اللَّهِ عَمَّا يُشْرِكُونَ} .فهو سبحانه المتكبر عن السوء، والنقص والعيوب، لعظمته وكبريائه.٦٩ - الْخَالِقُ،٧٠ - البَارِئُ، ٧١ - المُصَوِّرُ، ٧٢ - الْخَلاَّقُقال تعالى: {هُوَ اللَّهُ الخَالِقُ الْبَارِئُ المُصَوِّرُ لَهُ الأَسْمَاءُ الْحُسْنَى} . {إِنَّ رَبَّكَ هُوَ الْخَلاَّقُ الْعَلِيمُ} .الذي خلق جميع الموجودات وبرأها، وسوّاها
INSERT INTO "names" VALUES(72,'الخلاق','الْخَلاَّقُ','كثير الخلق والإبداع','٦٨ - المُتَكَبِّرُقال اللَّه تعالى: {هُوَ اللَّهُ الَّذِي لا إِلَهَ إِلاّ هُوَ الْمَلِكُ الْقُدُّوسُ السَّلامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ الْمُتَكَبِّرُ سُبْحَانَ اللَّهِ عَمَّا يُشْرِكُونَ} .فهو سبحانه المتكبر عن السوء، والنقص والعيوب، لعظمته وكبريائه.٦٩ - الْخَالِقُ،٧٠ - البَارِئُ، ٧١ - المُصَوِّرُ، ٧٢ - الْخَلاَّقُقال تعالى: {هُوَ اللَّهُ الخَالِقُ الْبَارِئُ المُصَوِّرُ لَهُ الأَسْمَاءُ الْحُسْنَى} . {إِنَّ رَبَّكَ هُوَ الْخَلاَّقُ الْعَلِيمُ} .الذي خلق جميع الموجودات وبرأها، وسوّاها
INSERT INTO "names" VALUES(73,'المؤمن','المُؤْمِنُ','الذي صدق رسله بالآيات وأمن عباده من الظلم','٧٣ - المُؤمنُالذي أثنى على نفسه بصفات الكمال، وبكمال الجلال والجمال، الذي أرسل رسله، وأنزل كتبه بالآيات والبراهين. وصدق رسله بكل آية وبرهان، يدلّ على صدقهم وصحة ما جاءوا به.٧٤ - المُهيمِنُالمطلع على خفايا الأمور، وخبايا الصدور، الذي أحاط بكل شيء علماً . وقال البغوي: الشهيد على عباده بأعمالهم وهو قول ابن عباس ومجاهد وغيرهما، يقال: هيمن يهيمن فهو مهيمن إذا كان رقيباً على الشيء ... .',171,'المبحث الخامس عشر: شرح أسماء الله الحسنى','https://shamela.ws/book/96493/171');
INSERT INTO "names" VALUES(74,'المهيمن','المُهيمِنُ','الرقيب الحافظ الشاهد على كل شيء','٧٣ - المُؤمنُالذي أثنى على نفسه بصفات الكمال، وبكمال الجلال والجمال، الذي أرسل رسله، وأنزل كتبه بالآيات والبراهين. وصدق رسله بكل آية وبرهان، يدلّ على صدقهم وصحة ما جاءوا به.٧٤ - المُهيمِنُالمطلع على خفايا الأمور، وخبايا الصدور، الذي أحاط بكل شيء علماً . وقال البغوي: الشهيد على عباده بأعمالهم وهو قول ابن عباس ومجاهد وغيرهما، يقال: هيمن يهيمن فهو مهيمن إذا كان رقيباً على الشيء ... .',171,'المبحث الخامس عشر: شرح أسماء الله الحسنى','https://shamela.ws/book/96493/171');
INSERT INTO "names" VALUES(75,'المحيط','المُحيطُ','الذي أحاط بكل شيء علما وقدرة وقهرا','٧٥ - المُحيطُقال اللَّه تعالى: {وَلِلَّهِ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ وَكَانَ اللَّهُ بِكُلِّ شَيْءٍ مُّحِيطًا} . وقال - عز وجل -: {وَإِن تَصْبِرُواْ وَتَتَّقُواْ لاَ يَضُرُّكُمْ كَيْدُهُمْ شَيْئًا إِنَّ اللَّهَ بِمَا يَعْمَلُونَ مُحِيطٌ} .وهو الذي أحاط بكل شيء علماً، وقدرة، ورحمة، وقهراً. وقد أحاط علمه بجميع المعلومات، وبصره بجميع المبصرات، وسمعه بجميع المسموعات، ونفذت مشيئته وقدرته بجميع الموجودات، ووسعت رحمته أهل الأرض والسموات، وقهر بعزّته كل مخلوق، ودانت له جميع الأشياء .',172,'المبحث الخامس عشر: شرح أسماء الله الحسنى','https://shamela.ws/book/96493/172');
INSERT INTO "names" VALUES(76,'المقيت','المُقيتُ','المقتدر الموصل لكل مخلوق ما يقوته','٧٦ - المُقِيتُقال اللَّه تعالى: {وَكَانَ اللَّهُ عَلَى كُلِّ شَيْءٍ
INSERT INTO "names" VALUES(77,'الوكيل','الوَكيلُ','المتولي أمور عباده الكافيهم ما أهمهم','٧٧ - الوَكيلُقال اللَّه تعالى: {اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ عَلَى كُلِّ
INSERT INTO "names" VALUES(78,'ذو الجلال والإكرام','ذو الجَلالِ والإكْرَامِ','المستحق للتعظيم والإكرام وحده','٧٨ - ذو الجَلالِ والإكْرَامِأي: ذو العظمة والكبرياء، وذو الرحمة، والجود، والإحسان العام والخاص.المُكْرِمُ لأوليائه وأصفيائه، الذين يُجلُّونه، ويُعظمونه، ويُحبونه . قال تعالى: {تَبَارَكَ اسْمُ رَبِّكَ ذِي الْجَلالِ وَالإِكْرَامِ} .',175,'المبحث الخامس عشر: شرح أسماء الله الحسنى','https://shamela.ws/book/96493/175');
INSERT INTO "names" VALUES(79,'جامع الناس ليوم لا ريب فيه','جَامِعُ النَّاسِ لِيَومٍ لا رَيْبَ فِيهِ','الذي يجمع الخلائق ليوم القيامة للحساب','٧٩ - جَامِعُ النَّاسِ لِيَومٍ لا رَيْبَ فِيهِقال اللَّه تعالى: {رَبَّنَا إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لاَّ رَيْبَ فِيهِ إِنَّ اللَّه لاَ يُخْلِفُ الْمِيعَادَ} . فاللَّه - سبحانه وتعالى - هو جامع الناس، وجامع أعمالهم وأرزاقهم، فلا يترك منها صغيرة ولا كبيرة إلا أحصاها.وجامع ما تفرق واستحال من الأموات الأولين والآخرين، بكمال قدرته، وسعة علمه .٨٠ - بَدِيعُ السَّمَوَاتِ وَالأرْضِقال اللَّه تعالى: {بَدِيعُ السَّمَوَاتِ وَالأَرْضِ وَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ} .أي: خالقهما ومبدعهما، في غاية ما يكون من الحسن والخلق البديع، والنظام العجيب المحكم.
INSERT INTO "names" VALUES(80,'بديع السموات والأرض','بَدِيعُ السَّمَوَاتِ وَالأرْضِ','المبدع للسماوات والأرض على غير مثال سابق','٧٩ - جَامِعُ النَّاسِ لِيَومٍ لا رَيْبَ فِيهِقال اللَّه تعالى: {رَبَّنَا إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لاَّ رَيْبَ فِيهِ إِنَّ اللَّه لاَ يُخْلِفُ الْمِيعَادَ} . فاللَّه - سبحانه وتعالى - هو جامع الناس، وجامع أعمالهم وأرزاقهم، فلا يترك منها صغيرة ولا كبيرة إلا أحصاها.وجامع ما تفرق واستحال من الأموات الأولين والآخرين، بكمال قدرته، وسعة علمه .٨٠ - بَدِيعُ السَّمَوَاتِ وَالأرْضِقال اللَّه تعالى: {بَدِيعُ السَّمَوَاتِ وَالأَرْضِ وَإِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُن فَيَكُونُ} .أي: خالقهما ومبدعهما، في غاية ما يكون من الحسن والخلق البديع، والنظام العجيب المحكم.
INSERT INTO "names" VALUES(81,'الكافي','الكَافي','الذي كفى عباده ما أهمهم من أمور دينهم ودنياهم','٨١ - الكَافيقال اللَّه تعالى: {أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ} ، فهو سبحانه الكافي عباده جميع ما يحتاجون ويضطرون إليه. الكافي كفاية خاصة، من آمن به، وتوكل عليه، واستمد منه حوائج دينه ودنياه.٨٢ - الواسِعُقال اللَّه تعالى: {وَاللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلاً وَاللَّهُ وَاسِعٌ عَلِيمٌ} . فهو - سبحانه وتعالى - واسع الصفات، والنعوت، ومتعلّقاتها، بحيث لا يُحصِي أحد ثَناءً عليه، بل هو كما أثنى على نفسه.
INSERT INTO "names" VALUES(82,'الواسع','الواسِعُ','الذي وسع كل شيء رحمة وعلما وغنى','٨١ - الكَافيقال اللَّه تعالى: {أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ} ، فهو سبحانه الكافي عباده جميع ما يحتاجون ويضطرون إليه. الكافي كفاية خاصة، من آمن به، وتوكل عليه، واستمد منه حوائج دينه ودنياه.٨٢ - الواسِعُقال اللَّه تعالى: {وَاللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلاً وَاللَّهُ وَاسِعٌ عَلِيمٌ} . فهو - سبحانه وتعالى - واسع الصفات، والنعوت، ومتعلّقاتها، بحيث لا يُحصِي أحد ثَناءً عليه، بل هو كما أثنى على نفسه.
INSERT INTO "names" VALUES(83,'الحق','الحَقُّ','الثابت الوجود الذي لا شك فيه','٨٣ - الحَقُّاللَّه - عز وجل - هو الحق في ذاته وصفاته، فهو واجب الوجود، كامل الصفات والنعوت، وجوده من لوازم ذاته، ولا وجود لشيء من الأشياء إلا به، فهو الذي لم يزل، ولا يزال، بالجلال، والجمال، والكمال، موصوفاً، ولم يزل ولا يزال بالإحسان معروفاً.فقوله حق، وفعله، حق، ولقاؤه حق، ورسله حق، وكتبه حق، ودينه هو الحق، وعبادته وحده لا شريك له، هي الحق، وكل شيء ينسب إليه، فهو حق . {ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ هُوَ الْبَاطِلُ وَأَنَّ اللَّهَ هُوَ الْعَلِيُّ الْكَبِيرُ} .{وَقُلِ الْحَقُّ مِن رَّبِّكُمْ فَمَن شَاءَ فَلْيُؤْمِن وَمَن شَاءَ
INSERT INTO "names" VALUES(84,'الجميل','الجَميلُ','الذي له الجمال المطلق في ذاته وصفاته وأفعاله','٨٤ - الجَميلُقال النبي - صلى الله عليه وسلم -: «إن اللَّه جميلٌ يحبُ الجمال» ، فهو سبحانه جميلٌ بذاته، وأسمائه، وصفاته، وأفعاله، فلا يُمكن مخلوقاً أن يعبر عن بعض جمال ذاته،
INSERT INTO "names" VALUES(85,'الرفيق','الرَّفيقُ','اللطيف بعباده الرفيق بهم في شرعه وقدره','٨٥ - الرَّفيقُمأخوذ من قول النبي - صلى الله عليه وسلم - في الحديث الصحيح: «إن اللَّه رفيق يحب الرفق، ويُعطي على الرفق ما لا يُعطي على العنف، وما لا يُعطي على ما سواه» ، فاللَّه تعالى رفيق في أفعاله، خلق المخلوقات كلها بالتدريج شيئاً فشيئاً بحسب حكمته ورفقه، مع أنه قادر على خلقها دفعة واحدة وفي لحظة واحدة.ومن تدبّر المخلوقات، وتدبّر الشرائع كيف يأتي بها شيئاً بعد شيء شاهد من ذلك العجب العجيب، فالمتأني الذي يأتي الأمور برفق وسكينة ووقار،
INSERT INTO "names" VALUES(86,'الحيي','الحَييُّ','الذي يستحيي من عبده إذا رفع يديه أن يردهما صفرا','٨٦ - الحَييُّ، ٨٧ - السِّتِّيرُهذا مأخوذ من قول النبي - صلى الله عليه وسلم -: «إن اللَّه حيي يستحي من عبده إذا مدَّ يديه إليه أن يردهما صفراً» 
INSERT INTO "names" VALUES(87,'الستير','السِّتِّيرُ','الذي يستر على عباده ذنوبهم وعيوبهم','٨٦ - الحَييُّ، ٨٧ - السِّتِّيرُهذا مأخوذ من قول النبي - صلى الله عليه وسلم -: «إن اللَّه حيي يستحي من عبده إذا مدَّ يديه إليه أن يردهما صفراً» 
INSERT INTO "names" VALUES(88,'الإله','الإلهُ','المعبود وحده الذي تألهه القلوب حبا وتعظيما','في طُغيانهم ولم يُنيبوا .٨٨ - الإلهُاسم الإله: هو الجامع لجميع صفات الكمال ونعوت الجلال، فقد دخل في هذا الاسم جميع الأسماء الحسنى؛ ولهذا كان القول الصحيح أنَّ «اللَّه» أصله «الإله»، وأن اسم «اللَّه» هو الجامع لجميع الأسماء الحسنى والصفات العلا، واللَّه أعلم . قال اللَّه تعالى: {إِنَّمَا اللَّهُ إِلَهٌ وَاحِدٌ سُبْحَانَهُ أَن يَكُونَ لَهُ وَلَدٌ لَّهُ مَا فِي السَّمَوَات وَمَا فِي الأَرْضِ وَكَفَى بِاللَّهِ وَكِيلاً} .',191,'المبحث الخامس عشر: شرح أسماء الله الحسنى','https://shamela.ws/book/96493/191');
INSERT INTO "names" VALUES(89,'القابض','القابضُ','الذي يقبض الرزق والأرواح بحكمته وعدله','٨٩ - القابضُ، ٩٠ - الباسِطُ، ٩١ - المُعطيقال اللَّه تعالى: {وَاللَّهُ يَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ تُرْجَعُونَ} ،
INSERT INTO "names" VALUES(90,'الباسط','الباسِطُ','الذي يبسط الرزق لمن يشاء بفضله وكرمه','٨٩ - القابضُ، ٩٠ - الباسِطُ، ٩١ - المُعطيقال اللَّه تعالى: {وَاللَّهُ يَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ تُرْجَعُونَ} ،
INSERT INTO "names" VALUES(91,'المعطي','المُعطي','الذي يعطي من يشاء ويمنع من يشاء بحكمته','٨٩ - القابضُ، ٩٠ - الباسِطُ، ٩١ - المُعطيقال اللَّه تعالى: {وَاللَّهُ يَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ تُرْجَعُونَ} ،
INSERT INTO "names" VALUES(92,'المقدم','المُقَدِّمُ','الذي يقدم من يشاء بفضله ويؤخر من يشاء بعدله','٩٢ - المُقَدِّمُ، ٩٣ - المُؤَخِّرُكان من آخر ما يقول النبي - صلى الله عليه وسلم - بين التشهد والتسليم: «اللَّهم اغفر لي ما قدّمت، وما أخَّرت، وما أسررتُ، وما أعلنتُ، وما أسرفت، وما أنت أعلمُ به مني. أنتَ المقدِّمُ، وأنت المؤخِّرُ. لا إله إلا أنت» .
INSERT INTO "names" VALUES(93,'المؤخر','المُؤَخِّرُ','الذي يؤخر من يشاء بحكمته وعدله','٩٢ - المُقَدِّمُ، ٩٣ - المُؤَخِّرُكان من آخر ما يقول النبي - صلى الله عليه وسلم - بين التشهد والتسليم: «اللَّهم اغفر لي ما قدّمت، وما أخَّرت، وما أسررتُ، وما أعلنتُ، وما أسرفت، وما أنت أعلمُ به مني. أنتَ المقدِّمُ، وأنت المؤخِّرُ. لا إله إلا أنت» .
INSERT INTO "names" VALUES(94,'المبين','المُبينُ','الذي أبان لعباده الحق من الباطل','٩٤ - المُبينُالمُبينُ: اسم الفاعل من أبان يُبينُ فهو مُبين، إذا أظهر وبَيَّن إما قولاً، وإما فعلاً.والبيِّنة هي الدلالة الواضحة عقلية كانت أو محسوسة، والبيان هو الكشف عن الشيء ... وسُمِّي الكلام بياناً لكشفه عن المقصود وإظهاره، نحو:
INSERT INTO "names" VALUES(95,'المنان','المنَّانُ','الذي يمن على عباده بالنعم العظيمة','٩٥ - المنَّانُالمنّان من أسماء اللَّه الحسنى التي سماه بها رسول اللَّه - صلى الله عليه وسلم -، فعن أنس بن مالك - رضي الله عنه - قال: سمع النبي - صلى الله عليه وسلم - رجلاً يقول: «اللَّهم إني أسألك بأن لك الحمد لا إله إلا أنت [وحدك لا شريك لك] المنّان، [يا] بديع السموات والأرض، يا ذا الجلال والإكرام، يا حيُّ يا قيوم إني أسألك الجنة وأعوذ بك من النار. فقال النبي - صلى الله عليه وسلم -: «لقد سأل اللَّه باسمه الأعظم الذي إذا سُئل به أعطى، وإذا دُعي به أجاب» .
INSERT INTO "names" VALUES(96,'الولي','الوليُّ','الناصر لعباده المؤمنين المتولي أمورهم','٩٦ - الوليُّالولي: يطلق على كل من وَلي أمراً أو قام به، والنصير، والمُحبّ، والصديق، والحليف، والصهر، والجار، والتابع، والمُعتِق، والمُطيع، يُقال: المؤمنُ
INSERT INTO "names" VALUES(97,'المولى','المَوْلَى','السيد الناصر المعين لعباده','٩٧ - المَوْلَى«المولى» اسم يقع على جماعة كثيرة، فهو: الربُّ، والمالكُ، والسَّيدُ، والمُنعمُ، والمُعتِقُ، والناصرُ، والمُحبُّ، والتابعُ، والجارُ، وابنُ العم، والحليفُ، والصِّهرُ، والعبدُ، والمنعمُ عليه، وأكثرها قد جاء في
INSERT INTO "names" VALUES(98,'النصير','النَّصِيرُ','الذي ينصر من يشاء ولا غالب لمن نصره','٩٨ - النَّصِيرُالنصير: فعيل بمعنى فاعل أو مفعول؛ لأن كل واحد من المتناصرين ناصرٌ ومنصورٌ وقد نصره ينصره نصراً إذا أعانه على عدوه وشدّ منه .والنصير هو الموثوق منه بأن لا يسلم وليه ولا يخذله . واللَّه - عز وجل - النصير، ونصره ليس كنصر المخلوق: {لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُالبَصِيرُ} ، وقد سمى نفسه تبارك وتعالى باسم النصير فقال: {وَكَفَى بِرَبِّكَ هَادِيًا وَنَصِيرًا} ، وقال تعالى: {وَاللَّهُ أَعْلَمُ بِأَعْدَائِكُمْ وَكَفَى بِاللَّهِ وَلِيًّا وَكَفَى بِاللَّهِ
INSERT INTO "names" VALUES(99,'الشافي','الشَّافِي','الذي يشفي القلوب من الشبهات والأبدان من الأمراض','٩٩ - الشَّافِيالشفاء في اللغة هو البرء من المرض. يقال: شفاه اللَّه يشفيه، واشتفى افتعل منه، فنقله من شفاء
INSERT INTO "quran_evidence" VALUES(1,1,'هُوَ الأَوَّلُ وَالآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ','سورة الحديد، الآية: ٣.');
INSERT INTO "quran_evidence" VALUES(2,2,'هُوَ الأَوَّلُ وَالآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ','سورة الحديد، الآية: ٣.');
INSERT INTO "quran_evidence" VALUES(3,3,'هُوَ الأَوَّلُ وَالآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ','سورة الحديد، الآية: ٣.');
INSERT INTO "quran_evidence" VALUES(4,4,'هُوَ الأَوَّلُ وَالآخِرُ وَالظَّاهِرُ وَالْبَاطِنُ','سورة الحديد، الآية: ٣.');
INSERT INTO "quran_evidence" VALUES(5,5,'وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ','سورة البقرة، الآية: ٢٥٥.');
INSERT INTO "quran_evidence" VALUES(6,5,'سَبِّحِ اسْمَ رَبِّكَالأَعْلَى','سورة الأعلى، الآية: ١.');
INSERT INTO "quran_evidence" VALUES(7,5,'عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ','سورة الرعد، الآية: ٩.');
INSERT INTO "quran_evidence" VALUES(8,5,'وَلاَ يُحِيطُونَ بِهِ عِلْمًا','سورة طه، الآية: ١١٠.');
INSERT INTO "quran_evidence" VALUES(9,6,'وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ','سورة البقرة، الآية: ٢٥٥.');
INSERT INTO "quran_evidence" VALUES(10,6,'سَبِّحِ اسْمَ رَبِّكَالأَعْلَى','سورة الأعلى، الآية: ١.');
INSERT INTO "quran_evidence" VALUES(11,6,'عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ','سورة الرعد، الآية: ٩.');
INSERT INTO "quran_evidence" VALUES(12,6,'وَلاَ يُحِيطُونَ بِهِ عِلْمًا','سورة طه، الآية: ١١٠.');
INSERT INTO "quran_evidence" VALUES(13,7,'وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ','سورة البقرة، الآية: ٢٥٥.');
INSERT INTO "quran_evidence" VALUES(14,7,'سَبِّحِ اسْمَ رَبِّكَالأَعْلَى','سورة الأعلى، الآية: ١.');
INSERT INTO "quran_evidence" VALUES(15,7,'عَالِمُ الْغَيْبِ وَالشَّهَادَةِ الْكَبِيرُ الْمُتَعَالِ','سورة الرعد، الآية: ٩.');
INSERT INTO "quran_evidence" VALUES(16,7,'وَلاَ يُحِيطُونَ بِهِ عِلْمًا','سورة طه، الآية: ١١٠.');
INSERT INTO "quran_evidence" VALUES(17,8,'وَلاَ يَؤُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ','سورة البقرة، الآية: ٢٥٥.');
INSERT INTO "quran_evidence" VALUES(18,8,'وَمَا قَدَرُوْا اللَّهَ حَقَّ قَدْرِهِ وَالأَرْضُ جَمِيعًا قَبْضَتُهُ يَوْمَ الْقِيَامَةِ وَالسَّموَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ','سورة الزمر، الآية: ٦٧.');
INSERT INTO "quran_evidence" VALUES(19,8,'إِنَّ اللَّهَ يُمْسِكُ السَّمَوَاتِ وَالأَرْضَ أَن تَزُولاَ وَلَئِن زَالَتَا إِنْ أَمْسَكَهُمَا مِنْ أَحَدٍ مِّن بَعْدِهِ','سورة فاطر، الآية: ٤١.');
INSERT INTO "quran_evidence" VALUES(20,8,'وَهُوَ الْعَلِيُّ
INSERT INTO "quran_evidence" VALUES(21,8,'تَكَادُ السَّمَوَاتُ يَتَفَطَّرْنَ مِن فَوْقِهِنَّ','سورة الشورى، الآية: ٥.');
INSERT INTO "quran_evidence" VALUES(22,8,'ذَلِكَ وَمَن يُعَظِّمْ شَعَائِرَ اللَّهِ فَإِنَّهَا مِن تَقْوَى الْقُلُوبِ','سورة الحج الآية ٣٢.');
INSERT INTO "quran_evidence" VALUES(23,8,'ذَلِكَ وَمَن يُعَظِّمْ حُرُمَاتِ اللَّهِ فَهُوَ خَيْرٌ لَّهُ عِندَ رَبِّهِ','سورة الحج الآية ٣٠.');
INSERT INTO "quran_evidence" VALUES(24,9,'رَحْمَتُ اللَّهِ وَبَرَكَاتُهُ عَلَيْكُمْ أَهْلَ الْبَيْتِ إِنَّهُ حَمِيدٌ مَّجِيدٌ','سورة هود، الآية: ٧٣.');
INSERT INTO "quran_evidence" VALUES(25,10,'ذَلِكُم بِأَنَّهُ إِذَا دُعِيَ اللَّهُ وَحْدَهُ كَفَرْتُمْ وَإِن يُشْرَكْ بِهِ تُؤْمِنُوا فَالْحُكْمُ للَّه الْعَلِيِّ الْكَبِيرِ','سورة غافر، الآية: ١٢.');
INSERT INTO "quran_evidence" VALUES(26,11,'وَكَانَ اللَّهُ سَمِيعًا بَصِيرًا','سورة النساء، الآية: ١٣٤.');
INSERT INTO "quran_evidence" VALUES(27,11,'سَوَاءٌ مِّنكُم مَّنْ أَسَرَّ الْقَوْلَ وَمَن جَهَرَ بِهِ وَمَنْ هُوَ مُسْتَخْفٍ بِاللَّيْلِ وَسَارِبٌ بِالنَّهَارِ','سورة الرعد، الآية: ١٠.');
INSERT INTO "quran_evidence" VALUES(28,11,'قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي
INSERT INTO "quran_evidence" VALUES(29,11,'قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا','سورة المجادلة، الآية: ١.');
INSERT INTO "quran_evidence" VALUES(30,11,'إِنَّ رَبِّي لَسَمِيعُ الدُّعَاءِ','سورة إبراهيم، الآية: ٣٩.');
INSERT INTO "quran_evidence" VALUES(31,12,'الَّذِي يَرَاكَ حِينَ تَقُومُ * وَتَقَلُّبَكَ فِي السَاجِدِينَ * إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ','سورة الشعراء، الآيات: ٢١٨ - ٢٢٠.');
INSERT INTO "quran_evidence" VALUES(32,12,'يَعْلَمُ خَائِنَةَ الأَعْيُنِ وَمَا تُخْفِي الصُّدُورُ','سورة غافر، الآية: ١٩.');
INSERT INTO "quran_evidence" VALUES(33,12,'وَاللَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ','سورة البروج، الآية: ٩.');
INSERT INTO "quran_evidence" VALUES(34,13,'وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ','سورة الأنعام، الآية: ١٨.');
INSERT INTO "quran_evidence" VALUES(35,13,'إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ','سورة الأنفال، الآية: ٧٥.');
INSERT INTO "quran_evidence" VALUES(36,13,'لَوْ كَانَ فِيهِمَا آلهَةٌ إِلاّ اللَّهُ لَفَسَدَتَا','سورة الأنبياء، الآية: ٢٢.');
INSERT INTO "quran_evidence" VALUES(37,13,'مَا اتَّخَذَ الَّهُ مِن
INSERT INTO "quran_evidence" VALUES(38,14,'وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ','سورة الأنعام، الآية: ١٨.');
INSERT INTO "quran_evidence" VALUES(39,14,'إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ','سورة الأنفال، الآية: ٧٥.');
INSERT INTO "quran_evidence" VALUES(40,14,'لَوْ كَانَ فِيهِمَا آلهَةٌ إِلاّ اللَّهُ لَفَسَدَتَا','سورة الأنبياء، الآية: ٢٢.');
INSERT INTO "quran_evidence" VALUES(41,14,'مَا اتَّخَذَ الَّهُ مِن
INSERT INTO "quran_evidence" VALUES(42,15,'يَا أَيُّهَا النَّاسُ أَنتُمُ الْفُقَرَاءُ إِلَى اللَّهِ وَاللَّهُ هُوَ الْغَنِيُّ الْحَمِيدُ','سورة فاطر، الآية: ١٥.');
INSERT INTO "quran_evidence" VALUES(43,16,'إِنَّ العِزَّةَ لِلَّهِ جَمِيعًا','سورة يونس، الآية: ٦٥.');
INSERT INTO "quran_evidence" VALUES(44,16,'إِنَّ رَبَّكَ هُوَ الْقَوِيُّ الْعَزِيزُ','سورة هود، الآية: ٦٦.');
INSERT INTO "quran_evidence" VALUES(45,16,'إِنَّ اللَّه هُوَ
INSERT INTO "quran_evidence" VALUES(46,16,'وَاللَّهُ قَدِيرٌ وَاللَّهُ غَفُورٌ رَّحِيمٌ','سورة الممتحنة، الآية: ٧.');
INSERT INTO "quran_evidence" VALUES(47,16,'قُلْ هُوَ الْقَادِرُ عَلَى أَن يَبْعَثَ عَلَيْكُمْ عَذَابًا مِّن فَوْقِكُمْ أَوْ مِن تَْتِ أَرْجُلِكُمْ أَوْ يَلْبِسَكُمْ شِيَعاً وَيُذِيقَ بَعْضَكُم بَأْسَ بَعْضٍ','سورة الأنعام، الآية: ٦٥.');
INSERT INTO "quran_evidence" VALUES(48,16,'وَكَانَ اللَّهُ عَلَى كُلِّ شَيْءٍ مُّقْتَدِرًا','سورة الكهف، الآية: ٤٥.');
INSERT INTO "quran_evidence" VALUES(49,16,'إِنَّ الْمُتَّقِينَ فِي جَنَّاتٍ وَنَهَرٍ * فِي مَقْعَدِ صِدْقٍ عِندَ مَلِيكٍ مُّقْتَدِرٍ','سورة القمر، الآيتان: ٥٤ - ٥٥.');
