INSERT INTO "quran_evidence" VALUES(91,22,'وَأَنَّهُ هُوَ أَغْنَى وَأَقْنَى','سورة النجم، الآية: ٤٨.');
INSERT INTO "quran_evidence" VALUES(92,22,'يَا أَيُّهَا النَّاسُ أَنتُمُ الْفُقَرَاءُ إِلَى اللَّهِ وَاللَّهُ هُوَ الْغَنِيُّ الْحَمِيدُ','سورة فاطر، الآية: ١٥.');
INSERT INTO "quran_evidence" VALUES(93,23,'وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ','سورة الأنعام، الآية: ١٨.');
INSERT INTO "quran_evidence" VALUES(94,24,'وَاعْلَمُواْ أَنَّ اللَّهَ يَعْلَمُ مَا فِي أَنفُسِكُمْ فَاحْذَرُوهُ وَاعْلَمُواْ أَنَّ اللَّهَ غَفُورٌ حَلِيمٌ','سورة البقرة، الآية: ٢٣٥.');
INSERT INTO "quran_evidence" VALUES(95,24,'وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِمَا كَسَبُوا مَا تَرَكَ عَلَى ظَهْرِهَا مِن دَابَّةٍ وَلَكِن يُؤَخِّرُهُمْ إِلَى أَجَلٍ مُّسَمًّى فَإِذَا جَاءَ أَجَلُهُمْ فَإِنَّ اللَّهَ كَانَ بِعِبَادِهِ بَصِيرًا','سورة فاطر، الآية: ٤٥.');
INSERT INTO "quran_evidence" VALUES(96,24,'وَلَوْ يُؤَاخِذُ اللَّهُ النَّاسَ بِظُلْمِهِم مَّا تَرَكَ عَلَيْهَا مِن دَآبَّةٍ وَلَكِن يُؤَخِّرُهُمْ إلَى أَجَلٍ مُّسَمًّى فَإِذَا جَاءَ أَجَلُهُمْ لاَ يَسْتَأْخِرُونَ سَاعَةً وَلاَ يَسْتَقْدِمُونَ','سورة النحل، الآية: ٦١.');
INSERT INTO "quran_evidence" VALUES(97,25,'إِنَّ اللَّه لَعَفُوٌّ غَفُورٌ','سورة الحج، الآية: ٦٠.');
INSERT INTO "quran_evidence" VALUES(98,25,'وَإِنِّي لَغَفَّارٌ لِّمَن تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى','سورة طه، الآية: ٨٢.');
INSERT INTO "quran_evidence" VALUES(99,25,'قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُواْ عَلَى أَنفُسِهِمْ لا تَقْنَطُواْ مِن رَّحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ','سورة الزمر، الآية: ٥٣.');
INSERT INTO "quran_evidence" VALUES(100,25,'إنَّ رَبَّكَ وَاسِعُ المَغْفِرَةِ','سورة النجم، الآية: ٣٢.');
INSERT INTO "quran_evidence" VALUES(101,26,'إِنَّ اللَّه لَعَفُوٌّ غَفُورٌ','سورة الحج، الآية: ٦٠.');
INSERT INTO "quran_evidence" VALUES(102,26,'وَإِنِّي لَغَفَّارٌ لِّمَن تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى','سورة طه، الآية: ٨٢.');
INSERT INTO "quran_evidence" VALUES(103,26,'قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُواْ عَلَى أَنفُسِهِمْ لا تَقْنَطُواْ مِن رَّحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ','سورة الزمر، الآية: ٥٣.');
INSERT INTO "quran_evidence" VALUES(104,26,'إنَّ رَبَّكَ وَاسِعُ المَغْفِرَةِ','سورة النجم، الآية: ٣٢.');
INSERT INTO "quran_evidence" VALUES(105,27,'إِنَّ اللَّه لَعَفُوٌّ غَفُورٌ','سورة الحج، الآية: ٦٠.');
INSERT INTO "quran_evidence" VALUES(106,27,'وَإِنِّي لَغَفَّارٌ لِّمَن تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَى','سورة طه، الآية: ٨٢.');
INSERT INTO "quran_evidence" VALUES(107,27,'قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُواْ عَلَى أَنفُسِهِمْ لا تَقْنَطُواْ مِن رَّحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ','سورة الزمر، الآية: ٥٣.');
INSERT INTO "quran_evidence" VALUES(108,27,'إنَّ رَبَّكَ وَاسِعُ المَغْفِرَةِ','سورة النجم، الآية: ٣٢.');
INSERT INTO "quran_evidence" VALUES(109,28,'أَلَمْ يَعْلَمُواْ أَنَّ اللَّهَ هُوَ يَقْبَلُ التَّوْبَةَ عَنْ عِبَادِهِ وَيَأْخُذُ الصَّدَقَاتِ وَأَنَّ اللَّهَ هُوَ التَّوَّابُ الرَّحِيمُ','سورة التوبة، الآية: ١٠٤.');
INSERT INTO "quran_evidence" VALUES(110,28,'فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّاباً','سورة النصر، الآية: ٣.');
INSERT INTO "quran_evidence" VALUES(111,29,'إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا','سورة النساء، الآية: ١.');
INSERT INTO "quran_evidence" VALUES(112,30,'إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا','سورة النساء، الآية: ١.');
INSERT INTO "quran_evidence" VALUES(113,30,'وَاللَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ','سورة المجادلة، الآية: ٦.');
INSERT INTO "quran_evidence" VALUES(114,31,'إِنَّ رَبِّي عَلَىَ كُلِّ شَيْءٍحَفِيظٌ','سورة هود، الآية: ٥٧.');
INSERT INTO "quran_evidence" VALUES(115,31,'أَعْطَى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَى','سورة طه، الآية: ٥٠.');
INSERT INTO "quran_evidence" VALUES(116,31,'إِنَّ اللَّهَ يُدَافِعُ عَنِ الَّذِينَ آمَنُوا','سورة الحج، الآية: ٣٨.');
INSERT INTO "quran_evidence" VALUES(117,32,'اللَّهُ لَطِيفٌ بِعِبَادِهِ يَرْزُقُ مَن يَشَاءُ
INSERT INTO "quran_evidence" VALUES(118,32,'لاَّ تُدْرِكُهُ الأَبْصَارُ وَهُوَ يُدْرِكُ الأَبْصَارَ وَهُوَ اللَّطِيفُ الْخَبِير','سورة الأنعام، الآية: ١٠٣.');
INSERT INTO "quran_evidence" VALUES(119,33,'هُوَ أَنَأَكُم مِّنَ الأَرْضِ وَاسْتَعْمَرَكُمْ فِيهَا فَاسْتَغْفِرُوهُ ثُمَّ تُوبُواْ إِلَيْهِ إِنَّ رَبِّي قَرِيبٌ مُّجِيبٌ','سورة هود، الآية: ٦١.');
INSERT INTO "quran_evidence" VALUES(120,33,'وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ','سورة البقرة، الآية: ١٨٦.');
INSERT INTO "quran_evidence" VALUES(121,34,'وَقَالَ رَبُّكُمُ
INSERT INTO "quran_evidence" VALUES(122,34,'أَمَّن يُجِيبُ الْمُضْطَرَّ إِذَا دَعَاهُ','سورة النمل، الآية: ٦٢.');
INSERT INTO "quran_evidence" VALUES(123,34,'إِنَّ رَبِّي قَرِيبٌ مُجِيبٌ','سورة هود، الآية: ٦١.');
INSERT INTO "quran_evidence" VALUES(124,35,'وَاسْتَغْفِرُواْ رَبَّكُمْ ثُمَّ تُوبُواْ إِلَيْهِ إِنَّ رَبِّي رَحِيمٌ وَدُودٌ','سورة هود، الآية: ٩٠.');
INSERT INTO "quran_evidence" VALUES(125,35,'وَهُوَ الْغَفُورُ الْوَدُودُ','سورة البروج، الآية: ١٤.');
INSERT INTO "quran_evidence" VALUES(126,35,'قُلْ إِن كُنتُمْ تُحِبُّونَ اللَّه فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ','سورة آل عمران، الآية: ٣١.');
INSERT INTO "quran_evidence" VALUES(127,36,'وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ اللَّهَ شَاكِرٌ عَلِيمٌ','سورة البقرة، الآية: ١٥٨.');
INSERT INTO "quran_evidence" VALUES(128,36,'إِن تُقْرِضُوا اللَّهَ قَرْضاً حَسَناً يُضَاعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ وَاللَّهُ شَكُورٌحَلِيمٌ','سورة التغابن، الآية: ١٧.');
INSERT INTO "quran_evidence" VALUES(129,36,'وَكَانَ اللَّهُ شَاكِراً عَلِيماً','سورة النساء، الآية: ١٤٧.');
INSERT INTO "quran_evidence" VALUES(130,36,'لا يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُونَ','سورة الأنبياء، الآية: ٢٣.');
INSERT INTO "quran_evidence" VALUES(131,36,'كَتَبَ رَبُّكُمْ عَلَى نَفْسِهِ الرَّحْمَةَ أَنَّهُ مَنْ عَمِلَ مِنكُمْ سُوءًا بِجَهَالَةٍ ثُمَّ تَابَ مِن بَعْدِهِ وَأَصْلَحَ فَأَنَّهُ غَفُورٌ رَّحِيمٌ','سورة الأنعام، الآية: ٥٤.');
INSERT INTO "quran_evidence" VALUES(132,36,'وَكَانَ حَقًّا عَلَيْنَا نَصْرُ الْمُؤْمِنِينَ','سورة الروم، الآية: ٤٧.');
INSERT INTO "quran_evidence" VALUES(133,37,'وَمَن تَطَوَّعَ خَيْرًا فَإِنَّ اللَّهَ شَاكِرٌ عَلِيمٌ','سورة البقرة، الآية: ١٥٨.');
INSERT INTO "quran_evidence" VALUES(134,37,'إِن تُقْرِضُوا اللَّهَ قَرْضاً حَسَناً يُضَاعِفْهُ لَكُمْ وَيَغْفِرْ لَكُمْ وَاللَّهُ شَكُورٌحَلِيمٌ','سورة التغابن، الآية: ١٧.');
INSERT INTO "quran_evidence" VALUES(135,37,'وَكَانَ اللَّهُ شَاكِراً عَلِيماً','سورة النساء، الآية: ١٤٧.');
INSERT INTO "quran_evidence" VALUES(136,37,'لا يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُونَ','سورة الأنبياء، الآية: ٢٣.');
INSERT INTO "quran_evidence" VALUES(137,37,'كَتَبَ رَبُّكُمْ عَلَى نَفْسِهِ الرَّحْمَةَ أَنَّهُ مَنْ عَمِلَ مِنكُمْ سُوءًا بِجَهَالَةٍ ثُمَّ تَابَ مِن بَعْدِهِ وَأَصْلَحَ فَأَنَّهُ غَفُورٌ رَّحِيمٌ','سورة الأنعام، الآية: ٥٤.');
INSERT INTO "quran_evidence" VALUES(138,37,'وَكَانَ حَقًّا عَلَيْنَا نَصْرُ الْمُؤْمِنِينَ','سورة الروم، الآية: ٤٧.');
INSERT INTO "quran_evidence" VALUES(139,38,'قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ','سورة الإخلاص، الآيتان: ١ - ٢.');
INSERT INTO "quran_evidence" VALUES(140,39,'قُلْ هُوَ اللَّهُ أَحَدٌ * اللَّهُ الصَّمَدُ','سورة الإخلاص، الآيتان: ١ - ٢.');
INSERT INTO "quran_evidence" VALUES(141,40,'قُلِ اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ الْوَاحِدُ الْقَهَّارُ','سورة الرعد آية ١٦.');
INSERT INTO "quran_evidence" VALUES(142,40,'يَوْمَ هُم بَارِزُونَ لا يَخْفَى عَلَى اللَّهِ مِنْهُمْ شَيْءٌ لِّمَنِ الْمُلْكُ الْيَوْمَ لِلَّهِ الْوَاحِدِ الْقَهَّارِ','سورة غافر، الآية: ١٦.');
INSERT INTO "quran_evidence" VALUES(143,40,'وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ','سورة الأنعام، الآية: ١٨.');
INSERT INTO "quran_evidence" VALUES(144,41,'قُلِ اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ الْوَاحِدُ الْقَهَّارُ','سورة الرعد آية ١٦.');
INSERT INTO "quran_evidence" VALUES(145,41,'يَوْمَ هُم بَارِزُونَ لا يَخْفَى عَلَى اللَّهِ مِنْهُمْ شَيْءٌ لِّمَنِ الْمُلْكُ الْيَوْمَ لِلَّهِ الْوَاحِدِ الْقَهَّارِ','سورة غافر، الآية: ١٦.');
INSERT INTO "quran_evidence" VALUES(146,41,'وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ وَهُوَ الْحَكِيمُ الْخَبِيرُ','سورة الأنعام، الآية: ١٨.');
INSERT INTO "quran_evidence" VALUES(147,42,'هُوَ اللَّهُ الَّذِي لا إِلَهَ إِلَّا هُوَ الْمَلِكُ الْقُدُّوسُ السَّلامُ الْمُؤْمِنُ الْمُهَيْمِنُ الْعَزِيزُ الْجَبَّارُ','سورة الحشر، الآية: ٢٣.');
INSERT INTO "quran_evidence" VALUES(148,43,'وَكَفَى بِاللَّهِ حَسِيبًا','سورة النساء، الآية: ٦.');
INSERT INTO "quran_evidence" VALUES(149,43,'أَلاَ لَهُ الْحُكْمُ وَهُوَ أَسْرَعُ الْحَاسِبِينَ','سورة الأنعام، الآية: ٦٢.');
INSERT INTO "quran_evidence" VALUES(150,43,'يَا أَيُّهَا النَّبِيُّ حَسْبُكَ اللَّهُ وَمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِينَ','سورة الأنفال، الآية: ٦٤.');
INSERT INTO "quran_evidence" VALUES(151,44,'وَكَفَى بِرَبِّكَ هَادِيًاوَنَصِيرًا','سورة الفرقان، الآية: ٣١.');
INSERT INTO "quran_evidence" VALUES(152,44,'وَإِنَّ اللَّهَ لَهَادِ الَّذِينَ آمَنُوا إِلَى صِرَاطٍ مُّسْتَقِيمٍ','سورة الحج، الآية: ٥٤.');
INSERT INTO "quran_evidence" VALUES(153,44,'رَبُّنَا الَّذِي أَعْطَى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَى','سورة طه، الآية: ٥٠.');
INSERT INTO "quran_evidence" VALUES(154,44,'وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا','سورة السجدة، الآية: ٢٤.');
INSERT INTO "quran_evidence" VALUES(155,44,'وَالَّذِينَ اهْتَدَوْا زَادَهُمْ هُدًى','سورة محمد، الآية: ١٧.');
INSERT INTO "quran_evidence" VALUES(156,44,'وَمَن يُؤْمِن بِاللَّه يَهْدِقَلْبَهُ','سورة التغابن، الآية: ١١.');
INSERT INTO "quran_evidence" VALUES(157,44,'إِنَّ الَّذِينَ آمَنُواْ وَعَمِلُواْ الصَّالِحَاتِ يَهْدِيهِمْ رَبُّهُمْ بِإِيمَانِهِمْ','سورة يونس، الآية: ٩.');
INSERT INTO "quran_evidence" VALUES(158,44,'وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا ...','سورة العنكبوت، الاية: ٦٩');
INSERT INTO "quran_evidence" VALUES(159,45,'فَاصْبِرُواْ حَتَّى يَحْكُمَ اللَّهُ بَيْنَنَا وَهُوَ خَيْرُ الْحَاكِمِينَ','سورة الأعراف، الآية: ٨٧.');
INSERT INTO "quran_evidence" VALUES(160,45,'وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلاً لاَّ مُبَدِّلِ لِكَلِمَاتِهِ','سورة الأنعام، الآية: ١١٥.');
INSERT INTO "quran_evidence" VALUES(161,45,'إِنَّ اللَّهَ يَأْمُرُ بِالْعَدْلِ وَالإِحْسَانِ','سورة النحل، الآية: ٩٠.');
INSERT INTO "quran_evidence" VALUES(162,45,'أَفَغَيْرَ اللَّهِ أَبْتَغِي حَكَمًا وَهُوَ الَّذِي
INSERT INTO "quran_evidence" VALUES(163,45,'وَنَضَعُ الْمَوَازِينَ الْقِسْطَ لِيَوْمِ الْقِيَامَةِ فَلا تُظْلَمُ نَفْسٌ شَيْئًا وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَى بِنَا حَاسِبِينَ','سورة الأنبياء، الآية: ٤٧.');
INSERT INTO "quran_evidence" VALUES(164,45,'إِنَّ رَبِّي عَلَى صِرَاطٍ مُّسْتَقِيمٍ','سورة هود، الآية: ٥٦.');
INSERT INTO "quran_evidence" VALUES(165,46,'هُوَ اللَّهُ الَّذِي لا إِلَهَ إِلا هُوَ الْمَلِكُ
INSERT INTO "quran_evidence" VALUES(166,46,'وَقُلِ الْحَمْدُ للَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا * وَلَم يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُن لَّهُ وَلِيٌّ مِّنَ الذُّلِّ وَكَبِّرْهُ تَكْبِيراً','سورة الإسراء، الآية: ١١١.');
INSERT INTO "quran_evidence" VALUES(167,47,'هُوَ اللَّهُ الَّذِي لا إِلَهَ إِلا هُوَ الْمَلِكُ
INSERT INTO "quran_evidence" VALUES(168,47,'وَقُلِ الْحَمْدُ للَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا * وَلَم يَكُن لَّهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُن لَّهُ وَلِيٌّ مِّنَ الذُّلِّ وَكَبِّرْهُ تَكْبِيراً','سورة الإسراء، الآية: ١١١.');
INSERT INTO "quran_evidence" VALUES(169,48,'إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ','سورة الطور، الآية: ٢٨.');
INSERT INTO "quran_evidence" VALUES(170,48,'رَبَّنَا لاَ تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا وَهَبْ لَنَا مِن لَّدُنكَ رَحْمَةً إِنَّكَ أَنتَ الْوَهَّابُ','سورة آل عمران، الآية: ٨.');
INSERT INTO "quran_evidence" VALUES(171,48,'رَبَّنَا وَسِعْتَ كُلَّ
INSERT INTO "quran_evidence" VALUES(172,48,'وَرَحْمَتِي وَسِعَتْ كُلَّشَيْءٍ','سورة الأعراف، الآية: ١٥٦.');
INSERT INTO "quran_evidence" VALUES(173,48,'وَمَا بِكُم مِّن نِّعْمَةٍ فَمِنَ اللَّهِ','سورة النحل، الآية: ٥٣.');
INSERT INTO "quran_evidence" VALUES(174,48,'فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ الزَّكَاةَ وَالَّذِينَ هُم بِآيَاتِنَا يُؤْمِنُونَ * الَّذِينَ يَتَّبِعُونَ الرَّسُولَ النَّبِيَّ الأُمِّيَّ',NULL);
INSERT INTO "quran_evidence" VALUES(175,48,'إِنَّ رَحْمَتَ اللَّهِ قَرِيبٌ مِّنَ الْمُحْسِنِينَ','سورة الأعراف، الآية: ٥٦.');
INSERT INTO "quran_evidence" VALUES(176,48,'وَأَدْخِلْنِي بِرَحْمَتِكَ فِي عِبَادِكَ الصَّالِحِينَ','سورة النمل، الآية: ١٩.');
INSERT INTO "quran_evidence" VALUES(177,49,'إِنَّا كُنَّا مِن قَبْلُ نَدْعُوهُ إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ','سورة الطور، الآية: ٢٨.');
