INSERT INTO "quran_evidence" VALUES(185,50,'الْحَمْدُ للَّهِ رَبِّ الْعَالَمينَ* لرَّحْمنِ
INSERT INTO "quran_evidence" VALUES(186,50,'وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيٌّكَرِيمٌ','سورة النمل، الآية: ٤٠.');
INSERT INTO "quran_evidence" VALUES(187,50,'وَيُحَذِّرُكُمُ اللَّهُ نَفْسَهُ وَاللَّهُ رَؤُوفُ بِالْعِبَادِ','سورة آل عمران، الآية: ٣٠.');
INSERT INTO "quran_evidence" VALUES(188,50,'وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ','سورة الأعراف، الآية: ١٥٦.');
INSERT INTO "quran_evidence" VALUES(189,50,'اقْرَأْ وَرَبُّكَ الأَكْرَمُ * الَّذِي عَلَّمَ بِالْقَلَمِ * عَلَّمَ الإِنسَانَ مَا لَمْ يَعْلَمْ','سورة العلق، الآيات: ٣ - ٥.');
INSERT INTO "quran_evidence" VALUES(190,50,'الَّذِي خَلَقَ فَسَوَّى * وَالَّذِي قَدَّرَ فَهَدَى','سورة الأعلى، الآيتان: ٢ - ٣.');
INSERT INTO "quran_evidence" VALUES(191,50,'رَبُّنَا الَّذِي أَعْطَى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَى','سورة طه، الآية: ٥٠.');
INSERT INTO "quran_evidence" VALUES(192,50,'الَّذِي خَلَقَنِي فَهُوَ يَهْدِينِ','سورة الشعراء، الآية: ٧٨.');
