INSERT INTO "quran_evidence" VALUES(225,55,'قُلْ يَجْمَعُ بَيْنَنَا رَبُّنَا ثُمَّ يَفْتَحُ بَيْنَنَا بِالْحَقِّ وَهُوَ الْفَتَّاحُ الْعَلِيمُ','سورة سبأ، الآية: ٢٦.');
INSERT INTO "quran_evidence" VALUES(226,55,'مَا يَفْتَحِ اللَّهُ لِلنَّاسِ مِن رَّحْمَةٍ فَلا مُمْسِكَ لَهَا وَمَا يُمْسِكْ فَلا مُرْسِلَ لَهُ مِن بَعْدِهِ وَهُوَ الْعَزِيزُ الْحَكِيمُ','سورة فاطر، الآية: ٢.');
INSERT INTO "quran_evidence" VALUES(227,56,'إِنَّ اللَّهَ هُوَ الرَّزَّاقُ','سورة الذاريات، الآية: ٥٨.');
INSERT INTO "quran_evidence" VALUES(228,56,'وَمَا مِن دَآبَّةٍ فِي الأَرْضِ إِلاَّ عَلَى اللَّهِ رِزْقُهَا','سورة هود، الآية: ٦.');
INSERT INTO "quran_evidence" VALUES(229,57,'إِنَّ اللَّهَ هُوَ الرَّزَّاقُ','سورة الذاريات، الآية: ٥٨.');
INSERT INTO "quran_evidence" VALUES(230,57,'وَمَا مِن دَآبَّةٍ فِي الأَرْضِ إِلاَّ عَلَى اللَّهِ رِزْقُهَا','سورة هود، الآية: ٦.');
INSERT INTO "quran_evidence" VALUES(231,58,'اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ','سورة البقرة، الآية: ٢٥٥.');
INSERT INTO "quran_evidence" VALUES(232,58,'الم * اللَّهُ لا إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ','سورة آل عمران، الآيتان: ١ - ٢.');
INSERT INTO "quran_evidence" VALUES(233,58,'وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِ وَقَدْ خَابَ مَنْ حَمَلَ ظُلمًا','سورة طه، الآية: ١١١.');
INSERT INTO "quran_evidence" VALUES(234,59,'اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ','سورة البقرة، الآية: ٢٥٥.');
INSERT INTO "quran_evidence" VALUES(235,59,'الم * اللَّهُ لا إِلَهَ إِلاَّ هُوَ الْحَيُّ الْقَيُّومُ','سورة آل عمران، الآيتان: ١ - ٢.');
INSERT INTO "quran_evidence" VALUES(236,59,'وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِ وَقَدْ خَابَ مَنْ حَمَلَ ظُلمًا','سورة طه، الآية: ١١١.');
INSERT INTO "quran_evidence" VALUES(237,60,'اللَّهُ نُورُ السَّمَوَاتِ وَالأَرْضِ مَثَلُ نُورِهِ كَمِشْكَاةٍ فِيهَا مِصْبَاحٌ الْمِصْبَاحُ فِي زُجَاجَةٍ الزُّجَاجَةُ كَأَنَّهَا كَوْكَبٌ دُرِّيٌّ يُوقَدُ مِن شَجَرَةٍ مُّبَارَكَةٍ زَيْتُونِةٍ لا شَرْقِيَّةٍ وَلا غَرْبِيَّةٍ يَكَادُ زَيْتُهَا يُضِيءُ وَلَوْ لَمْ تَمْسَسْهُ نَارٌ نُّورٌ عَلَى نُورٍ يَهْدِي اللَّهُ لِنُورِهِ مَن يَشَاء','سورة النور، آية: ٣٥.');
INSERT INTO "quran_evidence" VALUES(238,60,'يَهْدِي اللَّهُ لِنُورِهِ مَن يَشَاءُ','سورة النور، آية: ٣٥.');
INSERT INTO "quran_evidence" VALUES(239,61,'قُلْ أَغَيْرَ اللَّهِ أَبْغِي رَبًّا وَهُوَ رَبُّ كُلِّ شَيْءٍ','سورة الأنعام، الآية: ١٦٤.');
