INSERT INTO "quran_evidence" VALUES(275,77,'اللَّهُ وَلِيُّ الَّذِينَ آمَنُواْ يُخْرِجُهُم مِّنَ الظُّلُمَاتِ إِلَى النُّوُرِ','سورة البقرة، الآية: ٢٥٧.');
INSERT INTO "quran_evidence" VALUES(276,78,'تَبَارَكَ اسْمُ رَبِّكَ ذِي الْجَلالِ وَالإِكْرَامِ','سورة الرحمن، الآية: ٧٨.');
INSERT INTO "quran_evidence" VALUES(277,79,'رَبَّنَا إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ لاَّ رَيْبَ فِيهِ إِنَّ اللَّه لاَ يُخْلِفُ الْمِيعَادَ','سورة آل عمران، الآية: ٩.');
