INSERT INTO "quran_evidence" VALUES(287,81,'أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ','سورة الزمر، الآية: ٣٦.');
INSERT INTO "quran_evidence" VALUES(288,81,'وَاللَّهُ يَعِدُكُم مَّغْفِرَةً مِّنْهُ وَفَضْلاً وَاللَّهُ وَاسِعٌ عَلِيمٌ','سورة البقرة، الآية: ٢٦٨.');
INSERT INTO "quran_evidence" VALUES(289,82,'أَلَيْسَ اللَّهُ بِكَافٍ عَبْدَهُ','سورة الزمر، الآية: ٣٦.');
