INSERT INTO "quran_evidence" VALUES(291,83,'ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِن دُونِهِ هُوَ الْبَاطِلُ وَأَنَّ اللَّهَ هُوَ الْعَلِيُّ الْكَبِيرُ','سورة الحج، الآية: ٦٢.');
INSERT INTO "quran_evidence" VALUES(292,83,'وَقُلِ الْحَقُّ مِن رَّبِّكُمْ فَمَن شَاءَ فَلْيُؤْمِن وَمَن شَاءَ
INSERT INTO "quran_evidence" VALUES(293,83,'فَذَلِكُمُ اللَّهُ رَبُّكُمُ الْحَقُّ فَمَاذَا بَعْدَ الْحَقِّ إِلاَّ الضَّلاَلُ','سورة يونس، الآية: ٣٢.');
INSERT INTO "quran_evidence" VALUES(294,83,'وَقُلْ جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ زَهُوقًا','سورة الإسراء، الآية: ٨١.');
INSERT INTO "quran_evidence" VALUES(295,83,'يَوْمَئِذٍ يُوَفِّيهِمُ اللَّهُ دِينَهُمُ الْحَقَّ وَيَعْلَمُونَ أَنَّ اللَّهَ هُوَ الْحَقُّ الْمُبِينُ','سورة النور، الآية: ٢٥.');
INSERT INTO "quran_evidence" VALUES(296,84,'وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا','سورة الأعراف، الآية: ١٨٠.');
INSERT INTO "quran_evidence" VALUES(297,84,'هَلْ تَعْلَمُ لَهُ سَمِيًّا','سورة مريم، الآية: ٦٥.');
INSERT INTO "quran_evidence" VALUES(298,84,'إِنَّ رَبِّي عَلَى صِرَاطٍ مُّسْتَقِيمٍ','سورة هود، الآية: ٥٦.');
INSERT INTO "quran_evidence" VALUES(299,84,'صُنْعَ اللَّهِ الَّذِي أَتْقَنَ كُلَّ شَيْءٍ','سورة النمل، الآية: ٨٨.');
INSERT INTO "quran_evidence" VALUES(300,84,'الَّذِي أَحْسَنَ كُلَّ شَيْءٍ خَلَقَهُ','سورة السجدة، الآية: ٧.');
INSERT INTO "quran_evidence" VALUES(301,84,'وَمَنْ أَحْسَنُ مِنَ اللَّهِ حُكْمًا لِّقَوْمٍ يُوقِنُونَ','سورة المائدة، الآية: ٥٠.');
INSERT INTO "quran_evidence" VALUES(302,84,'وَلِلَّهِ الْمَثَلُ الأَعْلَىَ','سورة النحل، الآية: ٦٠.');
INSERT INTO "quran_evidence" VALUES(303,86,'إِنَّ الَّذِينَ يُحِبُّونَ أَن تَشِيعَ الْفَاحِشَةُ فِي الَّذِينَ آمَنُوا لَهُمْ عَذَابٌ أَلِيمٌ فِي الدُّنْيَا وَالآخِرَةِ','سورة النور، الآية: ١٩.');
INSERT INTO "quran_evidence" VALUES(304,87,'إِنَّ الَّذِينَ يُحِبُّونَ أَن تَشِيعَ الْفَاحِشَةُ فِي الَّذِينَ آمَنُوا لَهُمْ عَذَابٌ أَلِيمٌ فِي الدُّنْيَا وَالآخِرَةِ','سورة النور، الآية: ١٩.');
INSERT INTO "quran_evidence" VALUES(305,88,'إِنَّمَا اللَّهُ إِلَهٌ وَاحِدٌ سُبْحَانَهُ أَن يَكُونَ لَهُ وَلَدٌ لَّهُ مَا فِي السَّمَوَات وَمَا فِي الأَرْضِ وَكَفَى بِاللَّهِ وَكِيلاً','سورة النساء، الآية: ١٧١.');
INSERT INTO "quran_evidence" VALUES(306,89,'وَاللَّهُ يَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ تُرْجَعُونَ','سورة البقرة، الآية: ٢٤٥.');
INSERT INTO "quran_evidence" VALUES(307,89,'قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَن تَشَاءُ وَتَنزِعُ الْمُلْكَ مِمَّن تَشَاءُ وَتُعِزُّ مَن تَشَاءُ وَتُذِلُّ مَن تَشَاءُ
INSERT INTO "quran_evidence" VALUES(308,89,'وَمَن يُهِنِ اللَّهُ فَمَا لَهُ مِن مُّكْرِمٍ','سورة الحج، الآية: ١٨.');
INSERT INTO "quran_evidence" VALUES(309,89,'مَن كَانَ يُرِيدُ الْعِزَّةَ فَلِلَّهِ الْعِزَّةُ جَمِيعًا','سورة فاطر، الآية: ١٠.');
INSERT INTO "quran_evidence" VALUES(310,89,'وَلِلَّهِ الْعِزَّةُ وَلِرَسُولِهِ وَلِلْمُؤْمِنِينَ','سورة المنافقون، الآية: ٨.');
INSERT INTO "quran_evidence" VALUES(311,90,'وَاللَّهُ يَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ تُرْجَعُونَ','سورة البقرة، الآية: ٢٤٥.');
INSERT INTO "quran_evidence" VALUES(312,90,'قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَن تَشَاءُ وَتَنزِعُ الْمُلْكَ مِمَّن تَشَاءُ وَتُعِزُّ مَن تَشَاءُ وَتُذِلُّ مَن تَشَاءُ
INSERT INTO "quran_evidence" VALUES(313,90,'وَمَن يُهِنِ اللَّهُ فَمَا لَهُ مِن مُّكْرِمٍ','سورة الحج، الآية: ١٨.');
INSERT INTO "quran_evidence" VALUES(314,90,'مَن كَانَ يُرِيدُ الْعِزَّةَ فَلِلَّهِ الْعِزَّةُ جَمِيعًا','سورة فاطر، الآية: ١٠.');
INSERT INTO "quran_evidence" VALUES(315,90,'وَلِلَّهِ الْعِزَّةُ وَلِرَسُولِهِ وَلِلْمُؤْمِنِينَ','سورة المنافقون، الآية: ٨.');
INSERT INTO "quran_evidence" VALUES(316,91,'وَاللَّهُ يَقْبِضُ وَيَبْسُطُ وَإِلَيْهِ تُرْجَعُونَ','سورة البقرة، الآية: ٢٤٥.');
INSERT INTO "quran_evidence" VALUES(317,91,'قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ تُؤْتِي الْمُلْكَ مَن تَشَاءُ وَتَنزِعُ الْمُلْكَ مِمَّن تَشَاءُ وَتُعِزُّ مَن تَشَاءُ وَتُذِلُّ مَن تَشَاءُ
INSERT INTO "quran_evidence" VALUES(318,91,'وَمَن يُهِنِ اللَّهُ فَمَا لَهُ مِن مُّكْرِمٍ','سورة الحج، الآية: ١٨.');
INSERT INTO "quran_evidence" VALUES(319,91,'مَن كَانَ يُرِيدُ الْعِزَّةَ فَلِلَّهِ الْعِزَّةُ جَمِيعًا','سورة فاطر، الآية: ١٠.');
INSERT INTO "quran_evidence" VALUES(320,91,'وَلِلَّهِ الْعِزَّةُ وَلِرَسُولِهِ وَلِلْمُؤْمِنِينَ','سورة المنافقون، الآية: ٨.');
INSERT INTO "quran_evidence" VALUES(321,92,'وَإِنْ يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلا كَاشِفَ لَهُ إِلَّا هُوَ','سورة الأنعام، الآية: ١٧.');
INSERT INTO "quran_evidence" VALUES(322,92,'قُلْ فَمَن يَمْلِكُ لَكُم مِّنَ اللَّهِ شَيْئًا إِنْ أَرَادَ بِكُمْ ضَرًّا أَوْ أَرَادَ بِكُمْ نَفْعًا بَلْ كَانَ اللَّهُ بِمَا تَعْمَلُونَ خَبِيرًا','سورة الفتح، الآية: ١١.');
INSERT INTO "quran_evidence" VALUES(323,93,'وَإِنْ يَمْسَسْكَ اللَّهُ بِضُرٍّ فَلا كَاشِفَ لَهُ إِلَّا هُوَ','سورة الأنعام، الآية: ١٧.');
INSERT INTO "quran_evidence" VALUES(324,93,'قُلْ فَمَن يَمْلِكُ لَكُم مِّنَ اللَّهِ شَيْئًا إِنْ أَرَادَ بِكُمْ ضَرًّا أَوْ أَرَادَ بِكُمْ نَفْعًا بَلْ كَانَ اللَّهُ بِمَا تَعْمَلُونَ خَبِيرًا','سورة الفتح، الآية: ١١.');
INSERT INTO "quran_evidence" VALUES(325,94,'هَذَا بَيَانٌ لِّلنَّاسِ','سورة آل عمران، الآية ١٣٨.');
INSERT INTO "quran_evidence" VALUES(326,94,'يَوْمَئِذٍ يُوَفِّيهِمُ اللَّهُ دِينَهُمُ الْحَقَّ وَيَعْلَمُونَ أَنَّ اللَّهَ هُوَ الْحَقُّ الْمُبِينُ','سورة النور، الآية: ٢٥.');
INSERT INTO "quran_evidence" VALUES(327,94,'إِنَّ الَّذِينَ يَكْتُمُونَ مَا أَنزَلْنَا مِنَ الْبَيِّنَاتِ وَالْهُدَى مِن
INSERT INTO "quran_evidence" VALUES(328,94,'وَقَالَ الَّذِينَ لاَ يَعْلَمُونَ لَوْلاَ يُكَلِّمُنَا اللَّهُ أَوْ تَأْتِينَا آيَةٌ كَذَلِكَ قَالَ الَّذِينَ مِن قَبْلِهِم مِّثْلَ قَوْلِهِمْ تَشَابَهَتْ قُلُوبُهُمْ قَدْ بَيَّنَّا الآيَاتِ لِقَوْمٍيُوقِنُونَ','سورة البقرة، الآية: ١١٨.');
INSERT INTO "quran_evidence" VALUES(329,94,'كَذَلِكَ يُبيِّنُ اللَّهُ لَكُمُ الآيَاتِ لَعَلَّكُمْ تَتَفَكَّرُونَ','سورة البقرة، الآية: ٢٦٦.');
INSERT INTO "quran_evidence" VALUES(330,94,'يُرِيدُ اللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ الَّذِينَ مِن قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ وَاللَّهُ عَلِيمٌحَكِيمٌ','سورة النساء، الآية: ٢٦.');
INSERT INTO "quran_evidence" VALUES(331,94,'قَدْ جَاءَكُم مِّنَ اللَّهِ نُورٌ وَكِتَابٌ
INSERT INTO "quran_evidence" VALUES(332,94,'انظُرْ كَيْفَ نُبَيِّنُ لَهُمُ الآيَاتِ ثُمَّ انظُرْ أَنَّى يُؤْفَكُونَ','سورة المائدة، الآية: ٧٥.');
INSERT INTO "quran_evidence" VALUES(333,95,'وَإِن تَعُدُّواْ نِعْمَتَ اللَّهِ لاَ تُحْصُوهَا إِنَّ الإِنسَانَ لَظَلُومٌ كَفَّارٌ','سورة إبراهيم، الآية: ٣٤.');
INSERT INTO "quran_evidence" VALUES(334,95,'لَقَدْ مَنَّ اللَّهُ عَلَى الْمُؤمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولاً مِّنْ أَنفُسِهِمْ يَتْلُوا عَلَيْهِمْ آيَاتِهِ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ وَإِن كَانُواْ مِن قَبْلُ لَفِي ضَلالٍ مُّبِينٍ','سورة آل عمران، الآية: ١٦٤.');
INSERT INTO "quran_evidence" VALUES(335,95,'لَقَدْ مَنَّ اللَّهُ عَلَى الْمُؤمِنِينَ','سورة آل عمران، الآية: ١٦٤.');
INSERT INTO "quran_evidence" VALUES(336,95,'كَذَلِكَ كُنتُم مِّن قَبْلُ فَمَنَّ اللَّهُ عَلَيْكُمْ فَتَبَيَّنُواْ إِنَّ اللَّهَ كَانَ بِمَا تَعْمَلُونَ خَبِيرًا','سورة النساء، الآية: ٩٤.');
INSERT INTO "quran_evidence" VALUES(337,95,'وَلَقَدْ
INSERT INTO "quran_evidence" VALUES(338,95,'وَلَقَدْ مَنَنَّا عَلَيْكَ مَرَّةً أُخْرَى','سورة طه، الآية: ٣٧.');
INSERT INTO "quran_evidence" VALUES(339,95,'وَنُرِيدُ أَن نَّمُنَّ عَلَى الَّذِينَ اسْتُضْعِفُوا فِي الأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ الْوَارِثِينَ','سورة القصص، الآية: ٥.');
INSERT INTO "quran_evidence" VALUES(340,95,'فَمَنَّ اللَّهُ عَلَيْنَا وَوَقَانَا عَذَابَ السَّمُومِ','سورة الطور، الآية: ٢٧.');
INSERT INTO "quran_evidence" VALUES(341,96,'لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ','سورة الشورى، الآية: ١١.');
INSERT INTO "quran_evidence" VALUES(342,96,'أَمِ اتَّخَذُوا مِن دُونِهِ أَوْلِيَاءَ فَاللَّهُ هُوَ الْوَلِيُّ وَهُوَ يُحْيِي المَوْتَى وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ','سورة الشورى، الآية: ٩.');
INSERT INTO "quran_evidence" VALUES(343,96,'وَهُوَ الَّذِي يُنَزِّلُ الْغَيْثَ مِن بَعْدِ مَا قَنَطُوا وَيَنشُرُ رَحْمَتَهُ وَهُوَ الْوَلِيُّ الْحَمِيدُ','سورة الشورى، الآية: ٢٨.');
INSERT INTO "quran_evidence" VALUES(344,96,'اللَّهُ وَلِيُّ الَّذِينَ آمَنُواْ يُخْرِجُهُم مِّنَ الظُّلُمَاتِ إِلَى النُّوُرِ وَالَّذِينَ كَفَرُواْ أَوْلِيَآؤُهُمُ الطَّاغُوتُ يُخْرِجُونَهُم مِّنَ النُّورِ إِلَى الظُّلُمَاتِ أُوْلَئِكَ أَصْحَابُ النَّارِ هُمْ فِيهَا خَالِدُونَ','سورة البقرة، الآية: ٢٥٧.');
INSERT INTO "quran_evidence" VALUES(345,96,'وإِنَّ الظَّالِمِينَ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ وَاللَّهُ وَلِيُّ الْمُتَّقِينَ','سورة الجاثية، الآية: ١٩.');
INSERT INTO "quran_evidence" VALUES(346,96,'إِنَّ وَلِيِّيَ اللَّهُ الَّذِي نَزَّلَ الْكِتَابَ وَهُوَ يَتَوَلَّى
INSERT INTO "quran_evidence" VALUES(347,96,'إِنَّ اللَّهَ يُدَافِعُ عَنِ الَّذِينَ آمَنُوا','سورة الحج، الآية: ٣٨.');
INSERT INTO "quran_evidence" VALUES(348,97,'لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ','سورة الشورى، الآية: ١١.');
INSERT INTO "quran_evidence" VALUES(349,97,'فَأَقِيمُوا الصَّلاةَ وَآتُوا الزَّكَاةَ وَاعْتَصِمُوا بِاللَّهِ هُوَ مَوْلاكُمْ فَنِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ','سورة الحج، الآية: ٧٨.');
INSERT INTO "quran_evidence" VALUES(350,97,'وَإِن
INSERT INTO "quran_evidence" VALUES(351,97,'ذَلِكَ بِأَنَّ اللَّهَ مَوْلَى الَّذِينَ آمَنُوا وَأَنَّ الْكَافِرِينَ لا مَوْلَى لَهُمْ','سورة محمد، الآية: ١١.');
INSERT INTO "quran_evidence" VALUES(352,97,'بَلِ اللَّهُ
INSERT INTO "quran_evidence" VALUES(353,97,'أَنتَ مَوْلاَنَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ','سورة البقرة، الآية: ٢٨٦.');
INSERT INTO "quran_evidence" VALUES(354,97,'إِن تَتُوبَا إِلَى اللَّهِ فَقَدْ صَغَتْ قُلُوبُكُمَا وَإِن تَظَاهَرَا عَلَيْهِ فَإِنَّ اللَّهَ هُوَ مَوْلاهُ وَجِبْرِيلُ وَصَالِحُ الْمُؤْمِنِينَ','سورة التحريم، الآية: ٤.');
INSERT INTO "quran_evidence" VALUES(355,97,'قَدْ فَرَضَ اللَّهُ لَكُمْ تَحِلَّةَ أَيْمَانِكُمْ وَاللَّهُ مَوْلاكُمْ وَهُوَ الْعَلِيمُ الْحَكِيمُ','سورة التحريم، الآية: ٢.');
INSERT INTO "quran_evidence" VALUES(356,98,'لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُالبَصِيرُ','سورة الشورى، الآية: ١١.');
INSERT INTO "quran_evidence" VALUES(357,98,'وَكَفَى بِرَبِّكَ هَادِيًا وَنَصِيرًا','سورة الفرقان، الآية: ٣١.');
INSERT INTO "quran_evidence" VALUES(358,98,'وَاللَّهُ أَعْلَمُ بِأَعْدَائِكُمْ وَكَفَى بِاللَّهِ وَلِيًّا وَكَفَى بِاللَّهِ
INSERT INTO "quran_evidence" VALUES(359,98,'وَاعْتَصِمُوا بِاللَّهِ هُوَ مَوْلاكُمْ فَنِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ','سورة الحج، الآية: ٧٨.');
INSERT INTO "quran_evidence" VALUES(360,98,'فَاعْلَمُواْ أَنَّ اللَّهَ مَوْلاَكُمْ نِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ','سورة الأنفال، الآية:٤٠.');
INSERT INTO "quran_evidence" VALUES(361,98,'إِن يَنصُرْكُمُ اللَّهُ فَلاَ غَالِبَ لَكُمْ وَإِن يَخْذُلْكُمْ فَمَن ذَا الَّذِي يَنصُرُكُم مِّن بَعْدِهِ وَعَلَى اللَّهِ فَلْيَتَوَكِّلِ الْمُؤْمِنُونَ','سورة آل عمران، الآية: ١٦٠.');
INSERT INTO "quran_evidence" VALUES(362,98,'يَا أَيُّهَا الَّذِينَ آمَنُوا إِن تَنصُرُوا اللَّهَ يَنصُرْكُمْ وَيُثَبِّتْ أَقْدَامَكُمْ','سورة محمد، الآية: ٧.');
INSERT INTO "quran_evidence" VALUES(363,98,'إِنَّا لَنَنصُرُ رُسُلَنَا وَالَّذِينَ آمَنُوا فِي الْحَيَاةِ الدُّنْيَا وَيَوْمَ يَقُومُ الأَشْهَادُ','سورة غافر، الآية: ٥١.');
INSERT INTO "quran_evidence" VALUES(364,99,'يَا أَيُّهَا النَّاسُ قَدْ جَاءَتْكُم مَّوْعِظَةٌ مِّن رَّبِّكُمْ وَشِفَاءٌ لِّمَا فِي الصُّدُورِ وَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ','سورة يونس، الآية: ٥٧.');
INSERT INTO "quran_evidence" VALUES(365,99,'وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِّلْمُؤْمِنِينَ وَلاَ يَزِيدُ الظَّالِمِينَ إَلاَّ خَسَارًا','سورة الإسراء، الآية: ٨٢.');
INSERT INTO "quran_evidence" VALUES(366,99,'قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ وَالَّذِينَ لا يُؤْمِنُونَ فِي آذَانِهِمْ وَقْرٌ
INSERT INTO "quran_evidence" VALUES(367,99,'قُلْ بِفَضْلِ اللَّهِ وَبِرَحْمَتِهِ فَبِذَلِكَ فَلْيَفْرَحُواْ هُوَ خَيْرٌ مِّمَّا يَجْمَعُونَ','سورة يونس، الآية: ٥٨.');
INSERT INTO "quran_evidence" VALUES(368,99,'قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ',NULL);
INSERT INTO "quran_evidence" VALUES(369,99,'قَاتِلُوهُمْ يُعَذِّبْهُمُ اللَّهُ بِأَيْدِيكُمْ وَيُخْزِهِمْ وَيَنصُرْكُمْ عَلَيْهِمْ وَيَشْفِ صُدُورَ قَوْمٍ مُّؤْمِنِينَ * وَيُذْهِبْ غَيْظَ قُلُوبِهِمْ وَيَتُوبُ اللَّهُ عَلَى مَن يَشَاءُ وَاللَّهُ عَلِيمٌ حَكِيمٌ','سورة التوبة، الآيتان: ١٤ - ١٥.');
INSERT INTO "quran_evidence" VALUES(370,99,'قُلْ هُوَ اللَّهُ أَحَدٌ',NULL);
INSERT INTO "quran_evidence" VALUES(371,99,'قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ',NULL);
