INSERT INTO "scholarly_statements" VALUES(1,8,'ابن عباس وغيره');
INSERT INTO "scholarly_statements" VALUES(2,15,'ابن القيم - رحمه الله - أن اللَّه حميد من وجهين:أحدهما: أنّ جميع المخلوقات ناطقة بحمده، فكل حمد وقع من أهل السموات والأرض الأوّلي');
INSERT INTO "scholarly_statements" VALUES(3,30,'السعدي - رحمه الله - تعالى: «الرقيب» و «الشهيد» مترادفان، وكلاهما يدلُّ على إحاطة سمع اللَّه بالمسموعات، وبصره بالمبصرات، وعلم');
INSERT INTO "scholarly_statements" VALUES(4,46,'ابن القيم - رحمه الله - في اسم «السلام»: [اللَّهُ] أحق بهذا الاسم من كل مسمىً له؛ لسلامته سبحانه من كل عيب ونقص من كل وجه، فهو ال');
INSERT INTO "scholarly_statements" VALUES(5,47,'ابن القيم - رحمه الله - في اسم «السلام»: [اللَّهُ] أحق بهذا الاسم من كل مسمىً له؛ لسلامته سبحانه من كل عيب ونقص من كل وجه، فهو ال');
INSERT INTO "scholarly_statements" VALUES(6,50,'ابن تيمية - رحمه الله - في تفسير قوله تعالى: {اقْرَأْ وَرَبُّكَ الأَكْرَمُ * الَّذِي عَلَّمَ بِالْقَلَمِ * عَلَّمَ الإِنسَانَ مَا');
INSERT INTO "scholarly_statements" VALUES(7,50,'السعدي - رحمه الله -: الرحمنُ، الرحيمُ، والبرُ، الكريمُ، الجوادُ، الرؤوفُ، الوهابُ - هذه الأسماء تتقارب معانيها، وتدلّ كلُّها');
INSERT INTO "scholarly_statements" VALUES(8,51,'ابن تيمية - رحمه الله - في تفسير قوله تعالى: {اقْرَأْ وَرَبُّكَ الأَكْرَمُ * الَّذِي عَلَّمَ بِالْقَلَمِ * عَلَّمَ الإِنسَانَ مَا');
