INSERT INTO "scholarly_statements" VALUES(15,54,'السعدي - رحمه الله -: الرحمنُ، الرحيمُ، والبرُ، الكريمُ، الجوادُ، الرؤوفُ، الوهابُ - هذه الأسماء تتقارب معانيها، وتدلّ كلُّها');
INSERT INTO "scholarly_statements" VALUES(16,60,'ابن القيم - رحمه الله - حذّر من اغترار من اغترّ من أهل التصوف، الذين لم يُفَرِّقوا بين نور الصفات وبين أنوار الإيمان والمعارف؛ فإ');
INSERT INTO "scholarly_statements" VALUES(17,60,'السعدي - رحمه الله -: من أسمائه جلّ جلاله ومن أوصافه «النور» الذي هو وصفه العظيم، فإنه ذو الجلال والإكرام، وذو البهاء والسبحات');
INSERT INTO "scholarly_statements" VALUES(18,73,'البغوي: الشهيد على عباده بأعمالهم وهو قول ابن عباس ومجاهد وغيرهما، يقال: هيمن يهيمن فهو مهيمن إذا كان رقيباً على الشيء');
INSERT INTO "scholarly_statements" VALUES(19,74,'البغوي: الشهيد على عباده بأعمالهم وهو قول ابن عباس ومجاهد وغيرهما، يقال: هيمن يهيمن فهو مهيمن إذا كان رقيباً على الشيء');
INSERT INTO "scholarly_statements" VALUES(20,76,'ابن كثير: {وَكَانَ اللَّهُ عَلَى كُلِّ شَيْءٍ مُّقِيتًا} أي حفيظاً');
INSERT INTO "scholarly_statements" VALUES(21,76,'ابن عباس - رضي الله عنهما -: مقتدراً، أو مجازياً');
INSERT INTO "scholarly_statements" VALUES(22,76,'مجاهد: شهيداً، وفي رواية عنه: حسيباً، وقيل: قديراً، وقيل: المقيت: الرازق، وقيل: مقيت لكل إنسان بقدر عمله (٤)');
INSERT INTO "scholarly_statements" VALUES(23,76,'قتادة: حافظاً، وقيل: معناه على كل حيوان مُقيتاً: أي يوصل القوت إليه (٣)');
INSERT INTO "scholarly_statements" VALUES(24,95,'ابن كثير: «لا تمنن بعملك على ربك تستكثره» (٤)، وقيل غير ذلك');
INSERT INTO "scholarly_statements" VALUES(25,96,'ابن تيمية وغيره؛ ولأنه جاء في رواية الحديث رواية أخرى: «فبي يسمع، وبي يُبصر، وبي يبطش وبي');
INSERT INTO "scholarly_statements" VALUES(26,99,'ابن القيم - رحمه الله -: «ومن المعلوم أن بعض الكلام له خواص ومنافع مجربة، فما الظنُّ بكلام رب العالمين الذي فضله على كل كلام كفضل');
INSERT INTO "scholarly_statements" VALUES(27,99,'ابن كثير - رحمه الله - في تفسير قوله تعالى: {يَخْرُجُ مِن بُطُونِهَا شَرَابٌ مُّخْتَلِفٌ أَلْوَانُهُ فِيهِ شِفَاءٌ لِلنَّاسِ}: م');
