CREATE TABLE hadith_evidence (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name_id INTEGER NOT NULL REFERENCES names(id),
            text TEXT NOT NULL,
            source TEXT
        );
وأنت الباطن فليس دونك شيء','أخرجه مسلم في كتاب الذكر والدعاء والتوبة والاستغفار، باب ما يقول عند النوم وأخذ المضجع، برقم ٢٧١٣.');
وأنت الباطن فليس دونك شيء','أخرجه مسلم في كتاب الذكر والدعاء والتوبة والاستغفار، باب ما يقول عند النوم وأخذ المضجع، برقم ٢٧١٣.');
