CREATE TABLE related_names (
            name_id INTEGER NOT NULL REFERENCES names(id),
            related_name TEXT NOT NULL,
            PRIMARY KEY (name_id, related_name)
        );
CREATE TABLE scholarly_statements (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name_id INTEGER NOT NULL REFERENCES names(id),
            statement TEXT NOT NULL
        );
CREATE TABLE sources (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name_id INTEGER NOT NULL REFERENCES names(id),
            source TEXT NOT NULL
        );
CREATE INDEX idx_quran_name ON quran_evidence(name_id);
CREATE INDEX idx_hadith_name ON hadith_evidence(name_id);
CREATE INDEX idx_scholarly_name ON scholarly_statements(name_id);
CREATE INDEX idx_sources_name ON sources(name_id);
